insert into content_batches (code, version, description, status) values ('lote-0001', 1, 'lote gerado pelo pipeline', 'em_staging') on conflict (code) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-fintec-002', 'contabilidade_geral', 'contabilidade_geral.escrituracao_debito_credito', array['concurso'], 'pt-BR', 'Uma sociedade comercial adquiriu mercadorias para revenda, no valor de R$ 8.000,00, para pagamento em 30 dias, sem incidência de tributos recuperáveis. O lançamento contábil correto dessa operação, pelo método das partidas dobradas, é:', array['Débito em Fornecedores (Passivo) e crédito em Estoques (Ativo), ambos por R$ 8.000,00.','Débito em Despesas com mercadorias (Resultado) e crédito em Caixa (Ativo), por R$ 8.000,00.','Débito em Estoques (Ativo) e crédito em Fornecedores (Passivo), ambos por R$ 8.000,00.','Débito em Caixa (Ativo) e crédito em Receita de vendas (Resultado), ambos por R$ 8.000,00.'], 2, 'A compra a prazo aumenta um ativo (Estoques, que recebe débito) e aumenta uma obrigação (Fornecedores, que recebe crédito). O lançamento invertido reduziria o estoque e a dívida, como numa devolução. Lançar despesa contra Caixa trata a compra como gasto consumido e paga à vista, o que contradiz o prazo e a finalidade de revenda. Debitar Caixa contra receita de vendas representa uma venda recebida, operação oposta à descrita.', 'facil', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-fintec-003', 'contabilidade_geral', 'contabilidade_geral.estoques_inventario', array['concurso'], 'pt-BR', 'Uma loja iniciou o mês com 100 unidades de um item a R$ 10,00 cada. Comprou 200 unidades a R$ 13,00 cada e, depois, vendeu 150 unidades. Adotando o método da média ponderada fixa (custo médio único do período), o Custo das Mercadorias Vendidas foi de', array['R$ 1.650,00','R$ 1.800,00','R$ 1.950,00','R$ 1.725,00'], 1, 'Custo médio = (100 x 10 + 200 x 13) / 300 = 3.600 / 300 = R$ 12,00; CMV = 150 x 12 = R$ 1.800,00. R$ 1.650,00 é o resultado do PEPS (100 x 10 + 50 x 13). R$ 1.950,00 é o do UEPS (150 x 13), que baixa primeiro as compras mais recentes. R$ 1.725,00 usa média simples dos preços (11,50), erro comum, pois ignora as quantidades de cada lote.', 'medio', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-fintec-004', 'contabilidade_geral', 'contabilidade_geral.demonstracoes', array['concurso'], 'pt-BR', 'Dados do exercício de uma empresa comercial: receita bruta de vendas R$ 200.000,00; impostos incidentes sobre as vendas R$ 30.000,00; custo das mercadorias vendidas R$ 80.000,00; despesas operacionais (vendas e administrativas) R$ 40.000,00. O resultado operacional na Demonstração do Resultado do Exercício é', array['lucro de R$ 50.000,00','lucro de R$ 80.000,00','lucro de R$ 90.000,00','lucro de R$ 120.000,00'], 0, 'Receita líquida = 200.000 - 30.000 = 170.000; lucro bruto = 170.000 - 80.000 = 90.000; resultado operacional = 90.000 - 40.000 = 50.000. O valor de 80.000 esquece de deduzir os impostos sobre vendas da receita bruta. O de 90.000 é o lucro bruto, anterior às despesas operacionais. O de 120.000 desconsidera as deduções e as despesas, subtraindo só o CMV da receita bruta.', 'medio', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-fintec-005', 'contabilidade_geral', 'contabilidade_geral.depreciacao_ativos', array['concurso'], 'pt-BR', 'Uma máquina foi adquirida por R$ 120.000,00, com valor residual estimado em R$ 12.000,00 e vida útil de 6 anos, depreciada pelo método linear. Decorridos exatamente 30 meses de uso, seu valor contábil líquido é de', array['R$ 70.000,00','R$ 102.000,00','R$ 75.000,00','R$ 63.000,00'], 2, 'Base depreciável = 120.000 - 12.000 = 108.000; quota anual = 18.000; em 2,5 anos acumula-se 45.000; valor contábil = 120.000 - 45.000 = 75.000. R$ 70.000 resulta de depreciar sobre o custo total, sem descontar o residual (20.000 x 2,5 = 50.000). R$ 102.000 considera apenas um ano de depreciação. R$ 63.000 subtrai o valor residual novamente, depois de ele já ter sido excluído da base depreciável.', 'medio', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-fintec-006', 'contabilidade_geral', 'contabilidade_geral.analise_balancos', array['concurso'], 'pt-BR', 'Um balanço apresenta: Ativo Circulante R$ 240.000,00; Realizável a Longo Prazo R$ 60.000,00; Ativo Não Circulante restante R$ 300.000,00; Passivo Circulante R$ 150.000,00; Passivo Não Circulante R$ 250.000,00. O índice de Liquidez Geral é', array['1,60','0,60','1,20','0,75'], 3, 'Liquidez Geral = (Ativo Circulante + Realizável a Longo Prazo) / (Passivo Circulante + Passivo Não Circulante) = 300.000 / 400.000 = 0,75. O valor 1,60 é a Liquidez Corrente (240.000/150.000), que ignora o longo prazo. O valor 0,60 usa só o Ativo Circulante no numerador, sem o realizável a longo prazo. O valor 1,20 divide o numerador correto apenas pelo passivo não circulante (300.000/250.000), omitindo o passivo circulante.', 'dificil', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-fintec-012', 'economia', 'economia.oferta_demanda', array['enem','vestibular','concurso'], 'pt-BR', 'Em um mercado, a demanda é Qd = 100 - 2P e a oferta é Qs = 20 + 3P, em que P é o preço em reais e Q a quantidade em unidades. A quantidade de equilíbrio, em unidades, é', array['60','80','68','52'], 2, 'No equilíbrio Qd = Qs: 100 - 2P = 20 + 3P, logo 80 = 5P e P = 16; substituindo, Q = 100 - 32 = 68 (e 20 + 48 = 68, conferindo). O valor 60 corresponde a erro de cálculo ao dividir 80 por 5 e usar 20 como preço. O valor 80 é a diferença entre os interceptos, não uma quantidade. O valor 52 usa P = 24 (sem dividir corretamente) e não satisfaz simultaneamente as duas equações.', 'medio', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', '2026-11-27'::date, '2027-11-27'::date from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-fintec-013', 'economia', 'economia.estruturas_mercado', array['enem','vestibular','concurso'], 'pt-BR', 'Um monopolista enfrenta a demanda inversa P = 100 - Q e tem custo marginal constante igual a 20. Maximizando o lucro, a quantidade produzida e o preço cobrado são, respectivamente:', array['Q = 40 e P = 60','Q = 80 e P = 20','Q = 60 e P = 40','Q = 50 e P = 50'], 0, 'O monopolista iguala receita marginal a custo marginal. Com P = 100 - Q, RMg = 100 - 2Q; igualando a 20, Q = 40 e P = 100 - 40 = 60. A combinação Q = 80 e P = 20 é a da concorrência perfeita (P = CMg), que não maximiza o lucro do monopolista. Q = 60 e P = 40 e Q = 50 e P = 50 satisfazem a curva de demanda, mas não a condição RMg = CMg, pois a receita marginal nesses pontos (-20 e 0) difere de 20.', 'dificil', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', '2026-11-27'::date, '2027-11-27'::date from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-fintec-014', 'economia', 'economia.teoria_consumidor_firma', array['enem','vestibular','concurso'], 'pt-BR', 'O preço de um bem aumentou 10% e a quantidade demandada caiu 15%. O módulo da elasticidade-preço da demanda nesse intervalo é', array['0,67','1,5','0,15','25'], 1, 'Elasticidade-preço = variação percentual da quantidade demandada / variação percentual do preço = 15/10 = 1,5 em módulo; sendo maior que 1, a demanda é elástica e a receita total cai quando o preço sobe. O valor 0,67 resulta de inverter o quociente (10/15). O valor 0,15 confunde a razão entre percentuais com a variação em pontos decimais. O valor 25 soma as variações percentuais, o que não corresponde à definição de elasticidade.', 'medio', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', '2026-11-27'::date, '2027-11-27'::date from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-fintec-016', 'economia', 'economia.politica_monetaria_fiscal', array['enem','vestibular','concurso'], 'pt-BR', 'Em um modelo keynesiano simples, sem impostos e sem setor externo, a propensão marginal a consumir é 0,8. Um aumento autônomo dos gastos do governo de R$ 50 bilhões eleva a renda de equilíbrio em', array['R$ 200 bilhões','R$ 40 bilhões','R$ 62,5 bilhões','R$ 250 bilhões'], 3, 'O multiplicador é 1/(1 - PMgC) = 1/0,2 = 5; logo a variação da renda é 5 x 50 = R$ 250 bilhões. O valor 200 usa um multiplicador de 4, que seria o de PMgC = 0,75. O valor 40 aplica a propensão sobre o gasto (0,8 x 50) e não considera as rodadas sucessivas de consumo. O valor 62,5 divide o gasto pela propensão (50/0,8), operação sem sentido econômico no modelo, pois ignora que o multiplicador usa a propensão a poupar.', 'medio', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', '2026-11-27'::date, '2027-11-27'::date from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-fintec-022', 'seguranca_informacao', 'seguranca_informacao.principios_cid', array['concurso'], 'pt-BR', 'Um analista implantou verificação por hash nos arquivos de um sistema, para detectar qualquer modificação não autorizada no conteúdo depois do armazenamento. O princípio da segurança da informação diretamente protegido por esse controle é:', array['confidencialidade, que garante que só pessoas autorizadas acessem a informação.','integridade, que garante que a informação não foi alterada de forma indevida.','disponibilidade, que garante o acesso à informação sempre que ela for necessária.','irretratabilidade, que garante que o autor não possa negar a autoria da operação.'], 1, 'Comparar o hash atual com o hash original revela se o conteúdo mudou, o que protege a integridade. A confidencialidade é obtida por controles como criptografia e controle de acesso, que o hash não oferece, pois ele não esconde o conteúdo. A disponibilidade depende de redundância, backup e continuidade do serviço. A irretratabilidade (não repúdio) exige mecanismos como a assinatura digital, que associa a operação a um autor, o que um hash simples não faz.', 'facil', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-fintec-023', 'seguranca_informacao', 'seguranca_informacao.criptografia', array['concurso'], 'pt-BR', 'Em uma assinatura digital baseada em criptografia de chave pública, o signatário gera a assinatura de um documento usando', array['a chave pública do destinatário, e apenas o destinatário a verifica com a sua chave privada.','a sua chave pública, e qualquer pessoa verifica a assinatura com a chave privada correspondente.','uma chave simétrica compartilhada, e apenas quem a conhece pode verificar a assinatura.','a sua chave privada, e qualquer pessoa verifica a assinatura com a chave pública correspondente.'], 3, 'Na assinatura digital, o signatário usa a própria chave privada (sobre o resumo do documento) e qualquer interessado confere com a chave pública dele, o que dá autenticidade, integridade e não repúdio. Cifrar com a chave pública do destinatário é a técnica de sigilo, não de assinatura. Gerar com a chave pública e verificar com a privada inverte os papéis e exporia a chave privada. Chave simétrica compartilhada não prova autoria, pois qualquer detentor poderia ter gerado a mesma assinatura.', 'medio', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-fintec-024', 'seguranca_informacao', 'seguranca_informacao.ameacas_malware', array['concurso'], 'pt-BR', 'Um usuário abriu um anexo de e-mail e, minutos depois, todos os seus documentos ficaram inacessíveis, com uma mensagem exigindo pagamento para a liberação. O tipo de código malicioso que melhor descreve esse comportamento é o:', array['spyware, que coleta em segredo informações do usuário e as envia a terceiros.','worm, que se propaga sozinho pelas redes explorando falhas, sem depender de anexos.','ransomware, que cifra os dados da vítima e exige resgate para devolver o acesso.','adware, que exibe propaganda indesejada e altera a página inicial do navegador.'], 2, 'O quadro descrito (arquivos inacessíveis e exigência de pagamento) caracteriza o ransomware, que usa criptografia para sequestrar dados. O spyware atua de modo discreto, espionando, sem bloquear arquivos nem exigir pagamento. O worm se destaca pela autopropagação sem ação do usuário, o que não é o ponto do caso. O adware causa incômodo publicitário e não torna os documentos inacessíveis nem pede resgate.', 'facil', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-fintec-025', 'seguranca_informacao', 'seguranca_informacao.controles_acesso', array['concurso'], 'pt-BR', 'Uma organização concede a cada empregado apenas as permissões estritamente necessárias para o desempenho de suas funções, revisando-as quando ele muda de setor. Esse procedimento aplica o princípio do', array['menor privilégio, que limita os direitos de acesso ao mínimo necessário às atividades.','privilégio total, que concede amplo acesso para evitar interrupções no trabalho.','defesa em profundidade, que sobrepõe várias camadas de proteção de natureza distinta.','controle discricionário, que permite ao próprio usuário repassar suas permissões a quem queira.'], 0, 'O princípio do menor privilégio reduz a superfície de ataque e o impacto de erros ou abusos ao dar só o acesso necessário e revisá-lo quando as funções mudam. Conceder acesso amplo é o oposto. A defesa em profundidade trata de camadas múltiplas de controles, não da quantidade de permissões individuais. O controle discricionário deixa o dono do recurso decidir quem acessa, o que não garante o limite mínimo descrito e pode ampliar os privilégios indevidamente.', 'medio', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-fintec-026', 'seguranca_informacao', 'seguranca_informacao.gestao_incidentes', array['concurso'], 'pt-BR', 'No ciclo de tratamento de incidentes de segurança, após a etapa de detecção e análise, que confirma a ocorrência e avalia seu alcance, a etapa seguinte, voltada a impedir que o incidente se espalhe, é a de', array['preparação, que define políticas, equipes e ferramentas antes que ocorram incidentes.','contenção, que isola sistemas afetados antes da erradicação e da recuperação.','atividade pós-incidente, que registra as lições aprendidas depois do retorno à normalidade.','recuperação, que restaura os sistemas ao funcionamento normal antes de qualquer isolamento.'], 1, 'Depois de confirmado o incidente, a prioridade é contê-lo: isolar máquinas ou redes afetadas para limitar os danos, seguindo-se erradicação e recuperação. A preparação vem antes do incidente, não depois da análise. As atividades pós-incidente, como lições aprendidas, ocorrem no fim do ciclo. Restaurar sistemas antes de contê-los pode reintroduzir o problema ou permitir que a ameaça continue ativa, comprometendo a recuperação.', 'dificil', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-fintec-027', 'banco_dados', 'banco_dados.modelo_er', array['concurso'], 'pt-BR', 'Em um modelo entidade-relacionamento, um aluno pode se matricular em várias disciplinas e cada disciplina pode ter vários alunos. Na implementação em um banco de dados relacional, esse relacionamento muitos-para-muitos é tratado, em regra, com', array['uma chave estrangeira de disciplina dentro da tabela de aluno, em coluna única.','uma chave estrangeira de aluno dentro da tabela de disciplina, em coluna única.','uma tabela associativa contendo as chaves estrangeiras de aluno e de disciplina.','a fusão das duas entidades em uma única tabela com colunas repetidas por matrícula.'], 2, 'Relacionamentos N:N exigem uma terceira tabela (associativa) que guarda as chaves das duas entidades, com cada linha representando uma ocorrência do relacionamento. Uma só chave estrangeira em uma das tabelas permitiria apenas relação 1:N, limitando o aluno a uma disciplina ou a disciplina a um aluno. Fundir as entidades com colunas repetidas viola a atomicidade (primeira forma normal), gera redundância e impõe um número máximo fixo de matrículas.', 'facil', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-fintec-028', 'banco_dados', 'banco_dados.sql_basico', array['concurso'], 'pt-BR', 'Considere a tabela pedido(id, cliente, valor), com as linhas (1,''A'',100), (2,''A'',50), (3,''B'',200), (4,''C'',30), (5,''B'',20) e (6,''A'',70). Executa-se: SELECT COUNT(*) FROM (SELECT cliente FROM pedido GROUP BY cliente HAVING SUM(valor) >= 200). O resultado dessa consulta é', array['1','3','2','6'], 2, 'A subconsulta agrupa por cliente: A soma 220, B soma 220 e C soma 30; o HAVING mantém A e B, e o COUNT(*) externo conta 2 linhas. O valor 1 ignora um dos dois clientes que alcançam o limite. O valor 3 conta todos os grupos, como se o HAVING não filtrasse. O valor 6 é o número de linhas da tabela, resultado de contar sem agrupar, o que não é o que a consulta faz.', 'medio', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-fintec-029', 'banco_dados', 'banco_dados.sql_basico', array['concurso'], 'pt-BR', 'A tabela a possui os ids 1, 2, 3 e 4. A tabela b possui a coluna a_id com os valores 1, 2 e NULL. Executa-se: SELECT COUNT(*) FROM a WHERE id NOT IN (SELECT a_id FROM b). O resultado é', array['2','0','3','4'], 1, 'Com NOT IN, se a subconsulta devolve algum NULL, a comparação id <> NULL resulta em desconhecido para os ids que não casam com valores não nulos; assim nenhuma linha satisfaz o predicado e o COUNT é 0. O valor 2 seria o esperado se o NULL fosse ignorado (ids 3 e 4), erro comum de quem aplica lógica de dois valores. O valor 3 e o valor 4 supõem filtros que não correspondem à lógica de três valores do SQL.', 'dificil', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-fintec-031', 'banco_dados', 'banco_dados.transacoes_acid', array['concurso'], 'pt-BR', 'Em uma transferência bancária, o sistema debitou R$ 500,00 da conta de origem, mas uma falha impediu o crédito na conta de destino. Para que o banco permaneça consistente, a transação deve ser desfeita por inteiro (rollback). Essa exigência decorre da propriedade ACID chamada', array['atomicidade, pois a transação é executada integralmente ou não é executada.','isolamento, pois transações concorrentes não podem enxergar dados parciais.','durabilidade, pois dados confirmados devem sobreviver a falhas posteriores do sistema.','consistência, pois todo estado final deve ser idêntico ao estado inicial da transação.'], 0, 'Atomicidade define que as operações de uma transação formam uma unidade indivisível: ou todas valem, ou nenhuma, por isso o débito é desfeito se o crédito falha. O isolamento trata da visibilidade entre transações simultâneas. A durabilidade garante a permanência do que foi confirmado (commit), e aqui nada foi confirmado. Consistência exige estado final válido segundo as regras, não idêntico ao inicial; uma transferência bem-sucedida altera saldos.', 'medio', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-fintec-032', 'banco_dados', 'banco_dados.indices_desempenho', array['concurso'], 'pt-BR', 'Uma tabela de clientes com milhões de linhas é consultada com frequência por meio de filtros de igualdade na coluna cpf, mas recebe poucas inserções. A medida mais adequada para melhorar o desempenho dessas consultas, com o custo de ocupar espaço adicional e tornar as escritas um pouco mais lentas, é', array['criar uma visão sobre a tabela, pois a visão armazena os dados fisicamente ordenados por cpf.','criar um índice sobre a coluna cpf, evitando a leitura sequencial de toda a tabela.','remover a chave primária, pois a verificação de unicidade torna lentas as consultas de leitura.','desnormalizar a tabela duplicando a coluna cpf em todas as linhas, para acelerar a busca.'], 1, 'Um índice (por exemplo, B-tree) em cpf permite localizar linhas sem varrer a tabela inteira, ao custo de espaço e de manutenção nas escritas, aceitável em tabela pouco alterada. Uma visão comum é apenas uma consulta nomeada e não armazena nem ordena dados. Remover a chave primária não acelera buscas por cpf e prejudica a integridade. Duplicar a coluna cpf já existente não cria caminho de acesso mais rápido e só aumenta a redundância.', 'medio', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-fintec-033', 'redes', 'redes.modelos_osi_tcpip', array['concurso'], 'pt-BR', 'No modelo OSI, a camada responsável pelo endereçamento lógico e pelo encaminhamento dos pacotes entre redes diferentes, função típica dos roteadores, é a camada de', array['enlace de dados (camada 2)','transporte (camada 4)','aplicação (camada 7)','rede (camada 3)'], 3, 'A camada de rede (3) trata do endereçamento lógico (como o IP) e do roteamento entre redes, função dos roteadores. A camada de enlace usa endereços físicos (MAC) dentro de um mesmo segmento de rede. A de transporte cuida da comunicação fim a fim entre processos, com portas e, no TCP, confiabilidade. A de aplicação oferece serviços diretamente aos programas do usuário, como navegação e e-mail, sem encaminhar pacotes.', 'facil', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-fintec-034', 'redes', 'redes.enderecamento_ip', array['concurso'], 'pt-BR', 'Uma sub-rede recebeu o bloco 192.168.10.0/26. Descontando o endereço de rede e o de broadcast, o número de endereços utilizáveis para dispositivos nessa sub-rede é', array['62','64','30','126'], 0, 'Com prefixo /26 restam 32 - 26 = 6 bits para hosts: 2^6 = 64 endereços, dos quais 2 (rede e broadcast) não são atribuíveis: 62. O valor 64 esquece de descontar esses dois endereços. O valor 30 corresponde a um prefixo /27, com 5 bits de host. O valor 126 corresponde a um prefixo /25, com 7 bits de host. A contagem correta decorre diretamente do número de bits de host.', 'medio', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-fintec-035', 'redes', 'redes.enderecamento_ip', array['concurso'], 'pt-BR', 'O host 172.16.45.77 pertence à rede 172.16.32.0, com máscara 255.255.240.0 (prefixo /20). O endereço de broadcast dessa sub-rede é', array['172.16.45.255','172.16.63.255','172.16.32.255','172.16.47.255'], 3, 'Com /20, o bloco no terceiro octeto tem tamanho 16 (256 - 240). A rede começa em 32 e vai de 32 a 47; o broadcast tem todos os bits de host em 1: 172.16.47.255. O endereço 172.16.45.255 usa o terceiro octeto do host, ignorando o tamanho do bloco. O 172.16.63.255 seria o broadcast do bloco seguinte (48 a 63). O 172.16.32.255 respeita só o último octeto como parte de host, mas o terceiro octeto também varia dentro do bloco.', 'dificil', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-fintec-036', 'redes', 'redes.enderecamento_ip', array['concurso'], 'pt-BR', 'Um host está configurado com o endereço 192.168.1.130 e a máscara 255.255.255.128 (prefixo /25). O endereço da sub-rede à qual ele pertence é', array['192.168.1.0','192.168.1.129','192.168.1.128','192.168.1.255'], 2, 'Com /25, o último octeto é dividido em dois blocos de 128 endereços: 0 a 127 e 128 a 255. O host .130 está no segundo bloco, cujo endereço de rede é 192.168.1.128 (AND bit a bit com a máscara). O 192.168.1.0 é a rede do primeiro bloco. O 192.168.1.129 é o primeiro endereço utilizável do bloco, não o endereço da rede. O 192.168.1.255 é o endereço de broadcast desse mesmo bloco.', 'medio', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-fintec-037', 'redes', 'redes.protocolos_aplicacao', array['concurso'], 'pt-BR', 'Ao digitar um nome de site no navegador, o computador precisa descobrir o endereço IP correspondente. O protocolo da camada de aplicação responsável por essa tradução de nomes em endereços é o', array['DHCP','SMTP','ARP','DNS'], 3, 'O DNS (Domain Name System) traduz nomes de domínio em endereços IP. O DHCP atribui automaticamente configurações de rede, como endereço IP e gateway, aos dispositivos, mas não resolve nomes de sites. O SMTP é usado no envio de mensagens de e-mail entre servidores. O ARP resolve endereços IP em endereços MAC dentro da rede local e não é um protocolo de aplicação de resolução de nomes.', 'facil', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-fintec-038', 'logica_programacao', 'logica_programacao.variaveis_tipos', array['concurso'], 'pt-BR', 'Considere o trecho em pseudocódigo: a recebe 17; b recebe 5; r recebe (a div b) + (a mod b), em que div é a divisão inteira e mod é o resto da divisão inteira. O valor final de r é', array['3','5','2','6'], 1, '17 div 5 = 3 (quociente inteiro) e 17 mod 5 = 2 (resto); a soma é 5. O valor 3 considera só o quociente. O valor 2 considera só o resto. O valor 6 resulta de arredondar a divisão para cima (4) em vez de usar a divisão inteira e somar o resto 2; o operador div descarta a parte fracionária, sem arredondar.', 'facil', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-fintec-039', 'logica_programacao', 'logica_programacao.estruturas_controle', array['concurso'], 'pt-BR', 'Considere o pseudocódigo: s recebe 0; para i de 1 até 10 faça: se (i mod 3 = 0) então continue; se (i > 8) então pare; s recebe s + i. Aqui, continue passa à próxima iteração e pare encerra o laço. O valor final de s é', array['45','27','36','30'], 1, 'Os valores de i somados são 1, 2, 4, 5, 7 e 8: os múltiplos de 3 (3, 6 e 9) são pulados pelo continue, e em i = 10 o pare encerra o laço antes de somar. Total 1+2+4+5+7+8 = 27. O valor 45 é a soma de 1 a 9, sem tratar nenhuma das condições. O valor 36 seria o resultado de somar 1 a 8, sem pular os múltiplos de 3. O valor 30 corresponde a somar os valores até 9 excluindo só múltiplos de 3 maiores que 3, o que não segue o fluxo do código.', 'medio', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-fintec-041', 'logica_programacao', 'logica_programacao.estruturas_dados', array['concurso'], 'pt-BR', 'Uma pilha (estrutura LIFO) começa vazia. Executam-se, em ordem: empilhar(1), empilhar(2), empilhar(3), desempilhar, empilhar(4), desempilhar, desempilhar. Depois dessas operações, o elemento no topo da pilha é', array['2','3','1','4'], 2, 'Estado da pilha (base a topo): [1], [1,2], [1,2,3]; o primeiro desempilhar remove 3 e deixa [1,2]; empilhar(4) dá [1,2,4]; os dois desempilhar seguintes removem 4 e depois 2, restando [1]. O topo é 1. O valor 2 seria o topo antes do último desempilhar. O valor 3 e o valor 4 já foram removidos. Em uma fila o raciocínio seria outro, mas a pilha sempre retira o último elemento inserido.', 'medio', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-fintec-043', 'informatica', 'informatica.planilhas', array['concurso'], 'pt-BR', 'Em uma planilha eletrônica, as células A1:A5 contêm 5, 12, 20, 8 e 15, e as células B1:B5 contêm 1, 2, 3, 4 e 5. A fórmula =SOMASE(A1:A5;">10";B1:B5) retorna', array['47','35','10','15'], 2, 'SOMASE soma os valores do intervalo de soma (B) nas linhas em que o critério se aplica ao intervalo A: 12 (linha 2), 20 (linha 3) e 15 (linha 5) são maiores que 10; somam-se B2 + B3 + B5 = 2 + 3 + 5 = 10. O valor 47 soma os próprios valores de A que atendem ao critério. O valor 35 soma os valores de A que atendem ao critério omitindo o 12. O valor 15 é a soma de todos os valores de B, ignorando o critério.', 'medio', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-fintec-044', 'informatica', 'informatica.planilhas', array['concurso'], 'pt-BR', 'Em uma planilha eletrônica, o intervalo A1:A5 contém: 10 em A1, o texto ''x'' em A2, 20 em A3, A4 vazia e 30 em A5. A fórmula =MÉDIA(A1:A5) retorna', array['12','15','30','20'], 3, 'A função MÉDIA ignora células com texto e células vazias quando elas estão dentro de um intervalo, calculando só sobre os números 10, 20 e 30: 60 / 3 = 20. O valor 12 divide 60 por 5, tratando texto e vazio como zero. O valor 15 divide por 4, contando uma das duas células ignoradas. O valor 30 é o maior valor do intervalo, não a média. A diferença entre contar ou não as células é o ponto central da questão.', 'dificil', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-fintec-045', 'informatica', 'informatica.seguranca_basica', array['concurso'], 'pt-BR', 'Uma empresa faz backup completo aos domingos e backups incrementais de segunda a quarta-feira. Se o disco falhar na quinta-feira de manhã, para restaurar os dados até o backup de quarta-feira será necessário usar', array['apenas o backup completo de domingo, pois ele contém todas as alterações da semana.','apenas o incremental de quarta-feira, pois ele contém as alterações de toda a semana.','o backup completo de domingo e os três incrementais, aplicados em ordem.','o backup completo de domingo e apenas o incremental de quarta-feira, que consolida os anteriores.'], 2, 'O backup incremental copia somente o que mudou desde o último backup de qualquer tipo; por isso a restauração exige o completo de base e todos os incrementais seguintes, em sequência: domingo + segunda + terça + quarta. Só o completo perderia as alterações posteriores. Só o incremental de quarta não tem os dados que não mudaram desde domingo. A consolidação em um único incremental é característica do backup diferencial, não do incremental.', 'facil', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-gest-001', 'adm_geral', 'adm_geral.teorias_administrativas', array['concurso'], 'pt-BR', 'Em uma fábrica, um operário recebe ordens do chefe de produção, do chefe de manutenção e do chefe de qualidade, que muitas vezes se contradizem. Na Teoria Clássica de Henri Fayol, esse arranjo fere diretamente um dos seus princípios. Qual?', array['Unidade de comando, segundo a qual cada subordinado deve receber ordens de um único superior.','Unidade de direção, segundo a qual todo grupo de atividades com o mesmo objetivo deve ter um só plano e um só chefe.','Divisão do trabalho, segundo a qual a especialização das tarefas aumenta a produtividade dos operários.','Centralização, segundo a qual a autoridade de decisão deve concentrar-se apenas na cúpula da organização.'], 0, 'O caso descreve um subordinado com vários superiores simultâneos, o que fere a unidade de comando de Fayol (um empregado, um chefe). A unidade de direção é parecida, mas trata de um único plano para atividades com o mesmo objetivo na organização, não da relação de mando individual. A divisão do trabalho trata de especialização e não é violada pelo caso. A centralização refere-se ao grau de concentração de decisões e também não é o ponto. Note que a supervisão funcional proposta por Taylor admitia justamente múltiplos chefes, o que a distingue da proposta de Fayol.', 'medio', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-gest-002', 'adm_geral', 'adm_geral.planejamento_estrategico', array['concurso'], 'pt-BR', 'Ao elaborar a análise SWOT (FOFA) de uma prefeitura, a equipe listou: ''redução prevista nos repasses federais no próximo exercício''. Esse item deve ser classificado como:', array['Fraqueza, pois representa uma limitação interna dos recursos disponíveis na prefeitura.','Ameaça, pois é um fator externo e desfavorável ao alcance dos objetivos.','Oportunidade, pois a escassez de recursos estimula a criatividade da gestão municipal.','Força, pois indica que a prefeitura conhece bem a sua dependência de transferências.'], 1, 'Na análise SWOT, forças e fraquezas pertencem ao ambiente interno, e oportunidades e ameaças pertencem ao ambiente externo. A redução de repasses decorre de decisão alheia à prefeitura e prejudica seus objetivos: é uma ameaça. Classificá-la como fraqueza confunde ambiente externo com interno. Chamá-la de oportunidade ignora que o efeito é desfavorável. Chamá-la de força é incorreto porque conhecer a dependência não é um atributo vantajoso do ambiente interno.', 'facil', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-gest-003', 'adm_geral', 'adm_geral.organizacao_estrutura', array['concurso'], 'pt-BR', 'Uma diretoria deseja reduzir níveis hierárquicos e aproximar a cúpula da base. Ao fazê-lo sem criar novas chefias, cada gerente passará a supervisionar mais subordinados diretos. Em termos de estrutura organizacional, essa mudança:', array['Verticaliza a estrutura e reduz a amplitude de controle de cada gerente.','Achata a estrutura e reduz a amplitude de controle de cada gerente.','Achata a estrutura e aumenta a amplitude de controle de cada gerente.','Verticaliza a estrutura e aumenta a amplitude de controle de cada gerente.'], 2, 'A amplitude de controle é o número de subordinados diretos de um gestor. Retirar níveis hierárquicos sem criar chefias faz a estrutura ficar achatada (menos níveis) e cada gerente passa a ter mais subordinados diretos, ou seja, maior amplitude. As demais combinações são incoerentes: estrutura vertical tem muitos níveis e, em geral, pequena amplitude, de modo que reduzir níveis nunca a verticaliza, e achatar com menos subordinados por gerente contradiz o enunciado.', 'medio', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-gest-004', 'adm_geral', 'adm_geral.direcao_lideranca', array['concurso'], 'pt-BR', 'No Grid Gerencial de Blake e Mouton, o estilo 9,9 (equipe) caracteriza o gestor que:', array['Demonstra elevada preocupação com a produção e mínima preocupação com as pessoas, impondo ordens e controles.','Demonstra mínima preocupação com a produção e elevada preocupação com as pessoas, priorizando o clima agradável.','Demonstra preocupação mediana com a produção e com as pessoas, buscando um equilíbrio de compromisso.','Demonstra alta preocupação com a produção e com as pessoas, buscando comprometimento mútuo.'], 3, 'No Grid, o primeiro número mede a preocupação com a produção e o segundo, a preocupação com as pessoas, ambos de 1 a 9. O estilo 9,9 combina o máximo nas duas dimensões, com foco em comprometimento e integração. O estilo 9,1 (autoridade-obediência) é o de alta produção e baixa preocupação com pessoas. O 1,9 (clube campestre) privilegia o clima em detrimento da produção. O 5,5 (homem organizacional) é o do equilíbrio mediano e do compromisso, e não o estilo de equipe.', 'dificil', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-gest-005', 'adm_geral', 'adm_geral.controle_desempenho', array['concurso'], 'pt-BR', 'O Balanced Scorecard, proposto por Kaplan e Norton, organiza indicadores de desempenho em perspectivas. Qual conjunto abaixo corresponde às quatro perspectivas clássicas do modelo?', array['Financeira, mercado, tecnologia, responsabilidade social e ambiental.','Financeira, clientes, processos internos, aprendizado e crescimento.','Custos, qualidade, produtividade, inovação e satisfação dos acionistas.','Planejamento, organização, direção, controle e avaliação dos resultados.'], 1, 'O Balanced Scorecard clássico traduz a estratégia em indicadores nas perspectivas financeira, dos clientes, dos processos internos e de aprendizado e crescimento. O conjunto com mercado, tecnologia e responsabilidade socioambiental mistura dimensões que não são as do modelo. A lista de custos, qualidade, produtividade e inovação reúne tipos de indicadores, não perspectivas. Planejamento, organização, direção e controle são as funções administrativas do processo administrativo, outro conceito.', 'medio', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-gest-006', 'adm_geral', 'adm_geral.cultura_mudanca', array['concurso'], 'pt-BR', 'No modelo de mudança organizacional de Kurt Lewin, a etapa em que a organização estabiliza os novos comportamentos, incorporando-os a normas, rotinas e sistemas de reconhecimento, é chamada de:', array['Descongelamento, que prepara as pessoas para abandonar hábitos e crenças anteriores.','Movimentação, que implanta novas práticas e experimenta novos comportamentos.','Diagnóstico, que identifica lacunas entre o desempenho atual e o desejado.','Recongelamento, que consolida e institucionaliza o novo padrão adotado.'], 3, 'O modelo de Lewin tem três etapas: descongelamento (gerar prontidão e questionar o status quo), mudança ou movimentação (implantar novas práticas) e recongelamento (consolidar e institucionalizar). O enunciado descreve a consolidação do novo padrão em normas e rotinas, que é o recongelamento. Descongelamento é a preparação inicial. A movimentação é a fase de implantação. O diagnóstico não é etapa do modelo de Lewin, pertencendo a modelos de desenvolvimento organizacional.', 'dificil', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-gest-007', 'adm_publica', 'adm_publica.modelos_gestao_publica', array['concurso'], 'pt-BR', 'O modelo burocrático de administração pública, inspirado em Max Weber, tem como característica central:', array['A ênfase em normas formais, hierarquia e impessoalidade, com controle rigoroso dos procedimentos.','A ênfase no controle a posteriori dos resultados, com autonomia ampla aos gestores e foco no cidadão-cliente.','A confusão entre patrimônio público e privado do governante, com cargos distribuídos por laços pessoais.','A contratualização de metas entre o Estado e agências autônomas, com flexibilização das regras de pessoal.'], 0, 'O modelo burocrático busca combater o nepotismo e a corrupção por meio de normas, hierarquia, divisão formal de tarefas, profissionalização e impessoalidade, controlando os procedimentos. A ênfase em resultados e no cidadão-cliente é traço do modelo gerencial. A confusão entre o público e o privado e a distribuição de cargos por laços pessoais caracterizam o patrimonialismo. A contratualização de metas com agências é instrumento da reforma gerencial.', 'facil', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-gest-008', 'adm_publica', 'adm_publica.reforma_gerencial', array['concurso'], 'pt-BR', 'A Emenda Constitucional nº 19/1998, vinculada à reforma gerencial do Estado brasileiro, acrescentou ao caput do art. 37 da Constituição Federal um princípio da administração pública. Qual?', array['Supremacia do interesse público.','Razoabilidade.','Eficiência.','Motivação.'], 2, 'A EC 19/1998 incluiu a eficiência entre os princípios expressos do art. 37, caput, da CF/88, ao lado de legalidade, impessoalidade, moralidade e publicidade. Supremacia do interesse público, razoabilidade e motivação são princípios reconhecidos pela doutrina ou por leis infraconstitucionais, mas não constam do caput do art. 37 da Constituição.', 'facil', '{"origin": "autoral_baseada_em_referencias", "refs": [{"citacao": "art. 37, caput, CF/88 (redação dada pela EC nº 19/1998)", "fonte": "planalto-cf88"}]}'::jsonb, 'publicavel', '2026-11-27'::date, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-gest-009', 'adm_publica', 'adm_publica.reforma_gerencial', array['concurso'], 'pt-BR', 'Comparando a administração pública burocrática com a gerencial, é correto afirmar que a gerencial:', array['Mantém o controle rígido a priori de todos os procedimentos, acrescentando apenas indicadores financeiros.','Abandona a profissionalização do serviço público, substituindo-a pela livre nomeação dos dirigentes.','Troca o foco no controle de procedimentos pelo foco em resultados, com maior autonomia aos gestores.','Elimina a necessidade de transparência, pois a avaliação por resultados dispensa a prestação de contas.'], 2, 'A administração gerencial pretende tornar o Estado mais eficiente, deslocando a ênfase do controle de processos para o de resultados e concedendo autonomia aos gestores em troca de responsabilização. Manter o controle rígido a priori descreve a lógica burocrática. A gerencial não abandona a profissionalização, mas a reforça com carreiras estratégicas. A avaliação por resultados exige mais, e não menos, transparência e prestação de contas.', 'medio', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-gest-010', 'adm_publica', 'adm_publica.governo_eletronico', array['concurso'], 'pt-BR', 'Dados abertos governamentais são úteis ao controle social e à inovação. Para que um conjunto de dados seja considerado aberto, em sentido técnico, ele deve ser:', array['Publicado em formato aberto e processável por máquina, com licença que permita o reúso.','Disponibilizado apenas em documento digitalizado como imagem, para impedir alterações indevidas.','Acessível somente mediante cadastro do interessado, para que o órgão registre cada consulta.','Divulgado em relatório anual consolidado, com os números arredondados para facilitar a leitura.'], 0, 'Dados abertos devem ser publicados em formatos abertos e estruturados, legíveis por máquina, e com permissão de reúso, o que viabiliza análise e cruzamento. Imagens digitalizadas não são processáveis por máquina. Exigir cadastro cria barreira de acesso incompatível com a ideia de abertura. Relatório anual consolidado e arredondado impede a análise detalhada que se espera de dados abertos.', 'medio', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-gest-011', 'adm_publica', 'adm_publica.accountability', array['concurso'], 'pt-BR', 'Em estudos de accountability, o controle exercido pelos tribunais de contas sobre os atos do Poder Executivo é classificado como:', array['Accountability vertical, exercida pelos eleitores sobre os governantes por meio do voto.','Accountability social, exercida exclusivamente por entidades privadas sem vínculo com o Estado.','Accountability vertical eleitoral, exercida pelo Legislativo mediante a interpelação do Executivo.','Accountability horizontal, exercida por instituições estatais que se fiscalizam mutuamente.'], 3, 'A distinção clássica atribuída a O''Donnell separa a accountability vertical (sociedade sobre os governantes, em especial pelo voto) da horizontal (agências estatais que controlam umas às outras, como tribunais de contas, Legislativo, Judiciário e Ministério Público). Como o tribunal de contas é órgão estatal que controla outro Poder, o caso é horizontal. A alternativa do voto descreve a vertical. A social envolve cidadãos, imprensa e organizações, e não instituições estatais. A última mistura o controle legislativo, que também é horizontal, com a eleitoral.', 'dificil', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-gest-017', 'arquivologia', 'arquivologia.ciclo_vital', array['concurso'], 'pt-BR', 'Segundo a Lei nº 8.159/1991, são considerados documentos intermediários aqueles que:', array['Sem uso corrente no órgão produtor, aguardam, por interesse administrativo, eliminação ou recolhimento para guarda permanente.','Estão em curso ou, mesmo sem movimentação, constituem objeto de consultas frequentes pelo órgão que os produziu.','Possuem valor histórico, probatório e informativo e devem ser definitivamente preservados em arquivo público.','Foram produzidos por entidades privadas e dependem de declaração de interesse público para integrar o acervo oficial.'], 0, 'O art. 8º, §2º, da Lei 8.159/91 define os intermediários como os que, sem uso corrente nos órgãos produtores, aguardam eliminação ou recolhimento para guarda permanente por interesse administrativo. A definição dos documentos em curso ou muito consultados é a dos correntes (§1º). A definição dos de valor histórico, probatório e informativo a preservar é a dos permanentes (§3º). A referência a entidades privadas e a declaração de interesse público trata de outro tema da lei e não define a fase intermediária.', 'medio', '{"origin": "autoral_baseada_em_referencias", "refs": [{"citacao": "art. 8º, §§ 1º a 3º, Lei nº 8.159/1991", "fonte": "planalto-lei8159"}]}'::jsonb, 'publicavel', '2026-11-27'::date, '2027-11-27'::date from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-gest-018', 'arquivologia', 'arquivologia.classificacao_avaliacao', array['concurso'], 'pt-BR', 'Segundo a Lei nº 8.159/1991, a eliminação de documentos produzidos por instituições públicas e de caráter público deve ocorrer:', array['Por decisão do dirigente do órgão produtor, desde que os documentos tenham sido digitalizados.','Mediante autorização da instituição arquivística pública, em sua esfera de competência.','Automaticamente, ao fim do prazo de cinco anos de guarda contado da data de produção do documento.','Mediante autorização do órgão de controle interno, independentemente da avaliação arquivística.'], 1, 'O art. 9º da Lei 8.159/91 condiciona a eliminação de documentos públicos à autorização da instituição arquivística pública na respectiva esfera de competência, após o processo de avaliação. A decisão isolada do dirigente, mesmo com digitalização, não basta. A lei não fixa prazo uniforme de cinco anos com eliminação automática, pois os prazos vêm da tabela de temporalidade. O controle interno não substitui a instituição arquivística nem dispensa a avaliação.', 'medio', '{"origin": "autoral_baseada_em_referencias", "refs": [{"citacao": "art. 9º, Lei nº 8.159/1991", "fonte": "planalto-lei8159"}]}'::jsonb, 'publicavel', '2026-11-27'::date, '2027-11-27'::date from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-gest-026', 'gestao_projetos', 'gestao_projetos.escopo_prazo_custo', array['concurso'], 'pt-BR', 'Um projeto tem quatro atividades: A (3 dias, sem predecessora), B (5 dias, depende de A), C (2 dias, depende de A) e D (4 dias, depende de B e de C). Considerando as dependências, qual é a duração mínima do projeto, dada pelo caminho crítico?', array['9 dias','14 dias','12 dias','10 dias'], 2, 'O projeto tem dois caminhos: A-B-D, com 3+5+4 = 12 dias, e A-C-D, com 3+2+4 = 9 dias. O caminho crítico é o mais longo e define a duração mínima: 12 dias. O valor 9 corresponde ao caminho mais curto, que tem folga. O valor 14 soma todas as atividades como se fossem sequenciais, ignorando que B e C podem ocorrer em paralelo. O valor 10 não decorre de nenhuma combinação válida dos caminhos.', 'dificil', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-gest-027', 'gestao_projetos', 'gestao_projetos.riscos_qualidade', array['concurso'], 'pt-BR', 'Para reduzir o impacto financeiro de um possível incêndio no depósito de um projeto, a equipe contratou um seguro. Essa resposta ao risco negativo é classificada como:', array['Mitigação, pois reduz a probabilidade de que o incêndio venha a ocorrer.','Aceitação ativa, pois a equipe reconhece o risco e mantém reserva própria para cobrir a perda.','Esquiva, pois elimina a causa do risco ao mudar o depósito para outro local.','Transferência, pois repassa a um terceiro o impacto financeiro caso o risco ocorra.'], 3, 'Contratar seguro transfere a terceiro as consequências financeiras do evento, o que caracteriza a transferência de risco; o risco continua existindo, mas o impacto é repassado. Mitigação reduz probabilidade ou impacto por ações próprias, como instalar sprinklers. A aceitação ativa mantém o risco com reservas da própria equipe. A esquiva elimina a causa, por exemplo mudando o plano para não usar o depósito.', 'facil', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-gest-029', 'pedagogia', 'pedagogia.fundamentos_historicos', array['concurso'], 'pt-BR', 'O movimento da Escola Nova, difundido no Brasil nas décadas de 1920 e 1930 e associado ao Manifesto dos Pioneiros da Educação Nova, propunha:', array['Concentrar o ensino na transmissão de conteúdos pelo professor, com ênfase na memorização e na disciplina.','Organizar o ensino a partir de objetivos comportamentais mensuráveis, no modelo tecnicista de planejamento.','Priorizar a educação exclusivamente confessional, sob responsabilidade das instituições religiosas.','Deslocar o centro do processo educativo do professor para o aluno, valorizando a experiência do estudante.'], 3, 'A Escola Nova, influenciada por autores como Dewey, defendia o aprender fazendo, a atividade e o interesse do aluno e a educação pública, laica e gratuita; o Manifesto de 1932 expressa esse ideário. O ensino centrado na transmissão e na memorização é o da pedagogia tradicional. Objetivos comportamentais mensuráveis marcam a pedagogia tecnicista, posterior. A educação exclusivamente confessional contraria o caráter laico defendido pelos escolanovistas.', 'medio', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-gest-030', 'pedagogia', 'pedagogia.teorias_aprendizagem', array['concurso'], 'pt-BR', 'Na teoria de Vygotsky, a zona de desenvolvimento proximal (ou iminente) corresponde:', array['Ao conjunto de tarefas que a criança já domina de forma autônoma, sem qualquer apoio de outra pessoa.','À fase do desenvolvimento em que a criança passa a operar logicamente sobre objetos concretos e situações reais.','À distância entre o que a criança faz sozinha e o que faz com ajuda de um parceiro mais experiente.','Ao intervalo de tempo que a criança leva para memorizar e reter uma informação nova apresentada pelo professor.'], 2, 'A zona de desenvolvimento proximal é a distância entre o nível de desenvolvimento real (o que a criança faz sozinha) e o potencial (o que faz com mediação de outra pessoa), sendo o espaço em que o ensino deve atuar. Tarefas já dominadas autonomamente indicam o desenvolvimento real. A fase de operações concretas é conceito de Piaget. O tempo de memorização não é um conceito vygotskiano.', 'facil', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-gest-031', 'pedagogia', 'pedagogia.teorias_aprendizagem', array['concurso'], 'pt-BR', 'Uma criança que chama todo animal de quatro patas de ''cachorro'' vê uma vaca e, ao receber explicações, cria um novo esquema para diferenciar os animais. Na teoria de Piaget, o ajuste dos esquemas existentes às características do novo objeto é denominado:', array['Assimilação, que incorpora o novo objeto aos esquemas já existentes sem modificá-los.','Acomodação, que modifica ou cria esquemas para dar conta do que a experiência apresenta.','Maturação, que depende exclusivamente do amadurecimento biológico do sistema nervoso.','Internalização, que transforma a atividade social externa em processo psicológico interno.'], 1, 'Na teoria piagetiana, a adaptação ocorre por assimilação e acomodação. Quando o esquema existente não dá conta do novo objeto, ele é modificado ou um novo é criado: acomodação, que conduz ao reequilíbrio. A assimilação seria chamar a vaca de ''cachorro''. A maturação é fator biológico e não descreve o ajuste dos esquemas. A internalização é conceito de Vygotsky, ligado à transformação do social em individual.', 'medio', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-gest-032', 'pedagogia', 'pedagogia.curriculo_bncc', array['concurso'], 'pt-BR', 'Sobre a Base Nacional Comum Curricular (BNCC), é correto afirmar que ela:', array['Define as aprendizagens essenciais da educação básica, orientando a elaboração dos currículos das redes e escolas.','Substitui os currículos de redes e escolas, que ficam proibidos de incluir conteúdos de parte diversificada.','Define metodologias de ensino obrigatórias e instrumentos de avaliação padronizados para todas as escolas do país.','Aplica-se apenas à educação infantil e aos anos iniciais do ensino fundamental, etapas de formação básica inicial.'], 0, 'A BNCC é um documento de caráter normativo que define as aprendizagens essenciais a que todos os estudantes têm direito ao longo da educação básica, orientando a construção de currículos adaptados às realidades locais e de propostas pedagógicas. Ela não substitui os currículos nem proíbe a parte diversificada. Não prescreve metodologias nem instrumentos únicos de avaliação, que são decisões das redes e escolas. Também não se restringe a duas etapas, pois abrange educação infantil, ensino fundamental e ensino médio.', 'medio', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-gest-033', 'pedagogia', 'pedagogia.avaliacao_aprendizagem', array['concurso'], 'pt-BR', 'Uma professora aplica pequenas atividades ao longo do bimestre para identificar dificuldades dos alunos e ajustar suas estratégias de ensino antes de qualquer nota final. Essa prática caracteriza a avaliação:', array['Formativa, voltada ao acompanhamento e à regulação do processo de ensino e aprendizagem.','Somativa, voltada à atribuição de nota final para fins de aprovação ao término do período.','Diagnóstica inicial, aplicada somente antes do começo do período letivo para mapear conhecimentos prévios.','Classificatória, voltada à ordenação dos alunos em ranking de desempenho.'], 0, 'A avaliação formativa ocorre durante o processo e fornece informações para ajustar o ensino e apoiar o aluno, como na descrição. A somativa tem função de balanço ao final de um período. A diagnóstica inicial mapeia conhecimentos prévios antes do início do trabalho. A classificatória ordena estudantes por desempenho e não tem a finalidade de ajustar a prática pedagógica.', 'facil', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-hum-001', 'historia', 'historia.Brasil Colonial', array['enem','vestibular'], 'pt-BR', 'O sistema de capitanias hereditárias foi adotado pela Coroa portuguesa para organizar a ocupação do território americano. Qual era a principal razão dessa escolha?', array['Criar um governo central forte, com funcionários pagos pela Coroa, para administrar cada região de forma uniforme e direta','Entregar a terra às comunidades indígenas para que elas organizassem a produção de açúcar','Transferir a particulares, os donatários, parte dos custos e dos riscos de povoar e defender a colônia','Garantir a liberdade de comércio da colônia com outras nações europeias desde o início'], 2, 'O sistema dividiu o litoral em faixas entregues a donatários, que investiam recursos próprios e recebiam direitos de governo e exploração; assim a Coroa reduzia gastos. Não havia governo central forte nesse modelo (ele veio depois, com o governo-geral); a terra não foi entregue a comunidades indígenas, que sofreram com a colonização; e o comércio colonial era monopolizado pela metrópole, não livre.', 'facil', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-hum-002', 'historia', 'historia.Brasil Colonial', array['enem','vestibular'], 'pt-BR', '''O engenho exigia grande extensão de terra, muitos braços e capital. O açúcar seguia em navios para Lisboa e de lá era vendido a mercados europeus; da Europa chegavam ferramentas, tecidos e vinho.'' (texto elaborado para esta questão)
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-hum-003', 'historia', 'historia.Era Vargas', array['enem','vestibular'], 'pt-BR', 'Durante o governo de Getúlio Vargas foram criadas leis que garantiram direitos como salário mínimo e jornada regulamentada, reunidas na Consolidação das Leis do Trabalho. Ao mesmo tempo, os sindicatos passaram a depender do reconhecimento do Estado. Esse conjunto de medidas revela que a política trabalhista do período', array['foi marcada pela total autonomia sindical e pelo fim da intervenção do Estado nas relações de trabalho','limitou-se a proteger trabalhadores rurais, deixando os urbanos sem nenhuma regulamentação','aboliu o salário e a jornada definidos em lei, entregando-os à negociação individual com patrões','combinou a ampliação de direitos com o controle estatal sobre a organização dos trabalhadores'], 3, 'A política trabalhista varguista teve dupla face: concedeu direitos sociais e, em contrapartida, enquadrou os sindicatos em estruturas oficiais ligadas ao Estado. A total autonomia sindical contradiz esse atrelamento; a ideia de proteger só o campo inverte a realidade, pois a legislação alcançou sobretudo o trabalho urbano; e abolir salário e jornada em lei contraria a criação do salário mínimo e da regulamentação da jornada.', 'medio', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-hum-004', 'historia', 'historia.Era Vargas', array['enem','vestibular'], 'pt-BR', 'Em 1937, o Congresso foi fechado e uma nova Constituição foi outorgada, inaugurando o Estado Novo. Para justificar a medida, o governo divulgou um documento falso que apontava um suposto plano comunista de tomada do poder (o Plano Cohen). Do ponto de vista da análise histórica, esse episódio exemplifica', array['a aplicação estrita da Constituição anterior, que previa o fechamento do Congresso em caso de ameaça','o uso do medo de uma ameaça política, real ou inventada, como pretexto para concentrar poder e suspender o jogo democrático','a transição negociada entre partidos rivais para ampliar a participação popular no governo, com mediação de autoridades estrangeiras','uma reação espontânea da população, que pediu o fim do Legislativo por meio de eleições diretas'], 1, 'O Plano Cohen era um documento forjado, usado como pretexto para o golpe: exemplo clássico de instrumentalização do anticomunismo para legitimar o autoritarismo. A Constituição anterior não previa o fechamento do Congresso; o golpe não foi transição negociada e reduziu, em vez de ampliar, a participação política; e não houve pedido popular por eleição direta, pois o processo eleitoral previsto para 1938 foi cancelado.', 'dificil', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-hum-005', 'historia', 'historia.Idade Média', array['enem','vestibular'], 'pt-BR', 'Na sociedade feudal europeia, um senhor concedia terras (feudo) a outro nobre, que em troca lhe jurava fidelidade e prestava auxílio militar. Essa relação de obrigações mútuas entre nobres é chamada de', array['servidão da gleba camponesa e hereditária','suserania e vassalagem','escambo mercantil','corporação de ofício'], 1, 'Suserania e vassalagem designam o vínculo entre o senhor que concede o feudo (suserano) e o nobre que o recebe e jura fidelidade (vassalo). A servidão da gleba liga o camponês à terra do senhor, não é relação entre nobres; o escambo é troca direta de mercadorias; e a corporação de ofício organizava artesãos nas cidades medievais.', 'facil', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-hum-006', 'historia', 'historia.Antiguidade', array['enem','vestibular'], 'pt-BR', '''Em nossa cidade, todos participam das decisões na assembleia, e as leis valem para todos os cidadãos igualmente.'' (texto elaborado para esta questão)
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-hum-007', 'historia', 'historia.Independência do Brasil', array['enem','vestibular'], 'pt-BR', 'Diferentemente de várias colônias espanholas da América, o Brasil tornou-se independente mantendo a monarquia, a unidade territorial e a escravidão. Essa trajetória está relacionada, entre outros fatores,', array['à presença da família real portuguesa na colônia e ao apoio das elites agrárias, interessadas em preservar a ordem social','à derrota militar completa dos portugueses por exércitos populares que aboliram a escravidão','à proclamação imediata de uma república federativa, com ampla participação política popular e consequente extinção da dinastia reinante','à fragmentação do território em vários países, como ocorreu com o antigo vice-reino espanhol'], 0, 'A transferência da corte em 1808 e a liderança de um membro da dinastia, D. Pedro, deram à independência caráter de continuidade, apoiada por elites que temiam mudanças sociais, sobretudo o fim da escravidão. A alternativa sobre derrota por exércitos populares e abolição não corresponde aos fatos; a república não foi proclamada em 1822; e o território não se fragmentou, o que o contrasta com a América espanhola.', 'medio', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-hum-008', 'historia', 'historia.Idade Contemporânea', array['enem','vestibular'], 'pt-BR', 'Na Conferência de Berlim, realizada entre 1884 e 1885, potências europeias estabeleceram regras para a ocupação do continente africano, sem a presença de representantes africanos. As fronteiras que resultaram desse período frequentemente', array['respeitaram os antigos reinos africanos e foram traçadas por líderes locais consultados','seguiram rigorosamente os limites naturais, como rios e montanhas, em todo o continente','ignoraram as divisões étnicas, linguísticas e políticas preexistentes, o que gerou tensões duradouras','foram definidas apenas após a independência, por acordo entre os novos Estados africanos'], 2, 'A partilha da África, no contexto do neocolonialismo, foi decidida pelas potências sem consulta aos povos locais e traçou fronteiras artificiais, que juntaram grupos rivais ou separaram povos unidos, com efeitos de longa duração. A ideia de que líderes locais traçaram as fronteiras é falsa; nem sempre se usaram limites naturais, com muitas linhas retas; e a definição ocorreu antes, no período colonial, não depois das independências.', 'dificil', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-hum-009', 'geografia', 'geografia.Clima', array['enem','vestibular'], 'pt-BR', 'Em regiões de serras próximas ao litoral, como em trechos da Serra do Mar, é comum chover muito nas encostas voltadas para o mar. O fenômeno que explica essa chuva é a precipitação', array['convectiva, em que o oceano evapora apenas à noite e forma nuvens sobre o continente','de origem polar, em que a neve derrete e escorre pelas escarpas','frontal estacionária, em que o ar quente e o frio nunca se encontram','orográfica, em que o ar úmido sobe a encosta, resfria-se e condensa'], 3, 'Na chuva orográfica, ventos úmidos do oceano encontram o relevo, sobem, resfriam e condensam o vapor, chovendo na vertente de barlavento. A convectiva depende do aquecimento do solo e não de barreira montanhosa; a ideia de neve derretendo não descreve chuva de encosta no clima brasileiro; e a chuva frontal ocorre justamente do encontro entre massas de ar de temperaturas diferentes.', 'facil', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-hum-010', 'geografia', 'geografia.Energia do Brasil', array['enem','vestibular'], 'pt-BR', 'A matriz elétrica brasileira tem forte participação da energia hidrelétrica. Em períodos prolongados de estiagem, os reservatórios baixam de nível e o país precisa acionar outras fontes. Esse quadro evidencia, como principal vulnerabilidade desse modelo,', array['a impossibilidade técnica de produzir eletricidade a partir da água em qualquer época do ano','a dependência do regime de chuvas, que varia no tempo e entre as regiões','o fato de a energia hidráulica ser fóssil e esgotar-se com rapidez após alguns anos de uso','a necessidade de queimar grandes volumes de carvão mineral dentro das usinas hidrelétricas'], 1, 'Usinas hidrelétricas dependem da vazão dos rios e do nível dos reservatórios; secas prolongadas reduzem a geração. A afirmação de que é impossível gerar em qualquer época é exagero; a água é fonte renovável, não fóssil; e hidrelétricas não queimam carvão, que é usado em termelétricas, acionadas como complemento.', 'medio', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-hum-011', 'geografia', 'geografia.Urbanização do Brasil', array['enem','vestibular'], 'pt-BR', '''As ruas de duas cidades vizinhas já não têm separação visível: o limite entre elas é só uma placa. Moradores de uma trabalham na outra e usam o mesmo transporte diariamente.'' (texto elaborado para esta questão)
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-hum-012', 'geografia', 'geografia.Biomas do Brasil', array['enem','vestibular'], 'pt-BR', 'O Cerrado é conhecido como ''berço das águas'' no Brasil. Essa expressão se justifica porque o bioma', array['abriga nascentes de grandes bacias, como as dos rios São Francisco, Tocantins-Araguaia e Paraná','concentra os maiores volumes de chuva do país, superando qualquer outro bioma brasileiro e sul-americano, ao longo de todo o ano','possui rios exclusivamente intermitentes, que enchem uma vez por década','abrange somente áreas litorâneas, onde os rios desembocam diretamente no mar'], 0, 'No Cerrado, em áreas de planalto, nascem rios que alimentam grandes bacias, daí a importância hídrica. A maior pluviosidade do país está na Amazônia; os rios do Cerrado são em geral perenes; e o bioma se estende pelo interior do Brasil Central, não só pelo litoral.', 'medio', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-hum-013', 'geografia', 'geografia.Hidrografia', array['enem','vestibular'], 'pt-BR', 'O potencial hidrelétrico de um rio é maior quando ele combina grande volume de água com desníveis no leito. Por isso, no Brasil, muitas usinas foram instaladas em rios', array['de planalto, que têm quedas e corredeiras','de planície, que são totalmente planos e largos','intermitentes, que secam todos os anos','subterrâneos, que correm em cavernas profundas'], 0, 'Rios de planalto apresentam desníveis (quedas, cataratas), o que facilita o aproveitamento da energia da água. Os de planície têm pouca queda, o que reduz o potencial; os intermitentes não fornecem vazão contínua; e os subterrâneos não são aproveitados em grandes usinas.', 'facil', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-hum-014', 'geografia', 'geografia.Geopolítica e globalização', array['enem','vestibular'], 'pt-BR', '''O telefone de uma marca é projetado em um país, seus componentes são fabricados em outros três e a montagem final ocorre em um quinto, que o exporta para o mundo.'' (texto elaborado para esta questão)
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-hum-015', 'geografia', 'geografia.Agricultura do Brasil', array['enem','vestibular'], 'pt-BR', 'A chamada Revolução Verde difundiu, a partir do século XX, sementes melhoradas, fertilizantes, defensivos e mecanização em grandes áreas. Entre seus efeitos mais discutidos, destaca-se', array['a eliminação total da necessidade de insumos externos, tornando o produtor autônomo','o aumento da produtividade, acompanhado de dependência de insumos industriais e pressões ambientais e sociais','a redução da produtividade, o que levou ao abandono das lavouras comerciais, como consequência do esgotamento imediato dos solos','a substituição completa da agricultura por atividades extrativas em florestas nativas'], 1, 'A Revolução Verde elevou a produtividade pelo pacote tecnológico, mas aumentou a dependência de insumos (sementes, fertilizantes, agrotóxicos), favoreceu grandes produtores e gerou impactos ambientais, como contaminação e erosão. Ela não eliminou insumos externos, mas os ampliou; não reduziu a produtividade; e não substituiu a agricultura por extrativismo.', 'dificil', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-hum-016', 'filosofia', 'filosofia.Contratualistas', array['enem','vestibular'], 'pt-BR', 'Para John Locke, os indivíduos possuem direitos naturais, como vida, liberdade e propriedade, que o Estado deve proteger. Se o governo viola esses direitos, a consequência teórica é que', array['o governo continua legítimo, pois o soberano é absoluto e dele não se pode discordar','os direitos naturais deixam de existir, pois só valem no estado de natureza','a propriedade passa ao Estado, que decide livremente quem pode possuí-la','os cidadãos podem resistir e substituir o governante, pois o poder deriva do consentimento'], 3, 'Em Locke, o contrato social cria o governo para proteger direitos naturais; o poder é limitado e fundamentado no consentimento, e seu abuso autoriza resistência. O soberano absoluto e irrecorrível é ideia mais próxima de Hobbes; os direitos naturais não desaparecem com o pacto; e a propriedade não é entregue ao Estado.', 'medio', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-hum-017', 'filosofia', 'filosofia.Platão', array['enem','vestibular'], 'pt-BR', 'Na alegoria da caverna, de Platão, prisioneiros acorrentados veem apenas sombras na parede e tomam-nas por realidade. O prisioneiro que se liberta e sai da caverna simboliza', array['o comerciante que, por riqueza, passa a dominar os demais prisioneiros da cidade, e passa a controlar o acesso de todos à luz','o filósofo que, pelo conhecimento, passa da aparência para a compreensão da realidade inteligível','o guerreiro que, por força física, destrói a caverna e acaba com o conhecimento','o artista que, por imaginação, cria novas sombras mais convincentes que as originais'], 1, 'Para Platão, sair da caverna é o percurso educativo e filosófico que leva do mundo sensível, de sombras e opiniões, ao mundo das ideias, o verdadeiro conhecimento. A riqueza, a força e a produção de aparências não são o que a alegoria valoriza; ao contrário, a criação de sombras convincentes manteria os prisioneiros na ilusão.', 'facil', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-hum-019', 'filosofia', 'filosofia.Nietzsche', array['enem','vestibular'], 'pt-BR', 'Na genealogia da moral, Nietzsche sugere que certos valores, como humildade e compaixão, surgiram como forma de os fracos reinterpretarem sua condição, a partir do ressentimento contra os fortes. A tese central desse argumento é que', array['os valores morais têm origem histórica e psicológica, e não um fundamento eterno e neutro','a moral cristã é a única expressão legítima da vontade de poder dos indivíduos superiores','os valores são inatos e idênticos em todas as épocas, independentemente da cultura','a razão científica, por si só, pode determinar o que é bom e mau para todos'], 0, 'Nietzsche investiga a genealogia dos valores, mostrando que são produzidos em contextos históricos por forças psicológicas como o ressentimento, e não por uma origem divina ou racional neutra. Ele criticava justamente a moral cristã, por isso não a vê como expressão da vontade de poder; rejeita valores universais e eternos; e não atribui à ciência o poder de fundar valores.', 'dificil', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-hum-020', 'filosofia', 'filosofia.Teoria do conhecimento', array['enem','vestibular'], 'pt-BR', 'Descartes propôs a dúvida metódica: duvidar de tudo o que pudesse ser posto em questão, até encontrar algo indubitável. Esse procedimento tinha o objetivo de', array['convencer as pessoas de que nada pode ser conhecido e de que a verdade não existe','provar que os sentidos são sempre confiáveis para conhecer o mundo exterior','encontrar uma base de certeza segura para construir o conhecimento','substituir o uso da razão por tradições aceitas sem exame crítico'], 2, 'A dúvida cartesiana é um método, não um fim: busca uma certeza firme, que Descartes encontra no ''penso, logo existo''. Ela não leva ao ceticismo absoluto, pois o objetivo é superá-lo; questiona os sentidos, que podem enganar; e valoriza a razão, rejeitando aceitar tradições sem exame.', 'facil', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-hum-021', 'sociologia', 'sociologia.Émile Durkheim', array['enem','vestibular'], 'pt-BR', 'Para Durkheim, fatos sociais são maneiras de agir, pensar e sentir que existem fora das consciências individuais e exercem coerção sobre elas. Um exemplo é', array['o gosto pessoal de alguém por determinado sabor de sorvete escolhido na hora','um sonho isolado que ocorre apenas a uma pessoa durante uma noite','o idioma que a pessoa aprende ao nascer e que orienta como ela se comunica','a opinião passageira que alguém forma sozinho sobre o tempo do dia'], 2, 'O idioma preexiste ao indivíduo, é compartilhado e se impõe a ele (exterioridade, generalidade e coercitividade). Os demais exemplos são individuais e variáveis: o gosto pessoal, o sonho e a opinião passageira não são externos nem impostos pela coletividade, logo não caracterizam fatos sociais.', 'facil', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-hum-022', 'sociologia', 'sociologia.Max Weber', array['enem','vestibular'], 'pt-BR', 'Um empresário recusa uma proposta muito lucrativa por ela exigir práticas que ele considera desonestas, embora isso reduza seus ganhos. Segundo a tipologia de Max Weber, sua ação é principalmente', array['racional com relação a valores, guiada por convicções éticas, independentemente do resultado','racional com relação a fins, guiada apenas pelo cálculo de lucro maior, sem considerar valores nem tradições','tradicional, guiada pelo costume e pelo hábito arraigado de gerações','afetiva, guiada por emoção intensa e impulsiva no momento da decisão'], 0, 'Quando alguém age por convicção ética, aceitando perder vantagens, trata-se de ação racional com relação a valores. Se a ação visasse ao lucro, seria racional com relação a fins; se seguisse hábito herdado, seria tradicional; e a afetiva é motivada por impulso emocional, o que o caso, de convicção deliberada, não descreve.', 'medio', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-hum-023', 'sociologia', 'sociologia.Karl Marx', array['enem','vestibular'], 'pt-BR', 'Para Marx, no capitalismo o trabalhador vende sua força de trabalho e produz mais valor do que recebe em salário. A parte do valor que fica com o capitalista é chamada de', array['renda vitalícia','câmbio fixo','capital simbólico','mais-valia'], 3, 'Mais-valia é o valor excedente criado pelo trabalho além do necessário para pagar o salário, apropriado pelo dono dos meios de produção. Renda vitalícia e câmbio fixo são conceitos de outros contextos, e capital simbólico pertence ao vocabulário de Pierre Bourdieu, não ao de Marx.', 'medio', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-hum-024', 'sociologia', 'sociologia.Indústria cultural e mídia', array['enem','vestibular'], 'pt-BR', 'Adorno e Horkheimer criticaram a indústria cultural por produzir bens culturais em série, voltados ao consumo rápido. Segundo essa crítica, o efeito social dessa lógica é', array['a ampliação irrestrita da criatividade, pois cada obra é única e irrepetível','a padronização do gosto e a redução do potencial crítico do público','o fim do mercado cultural, pois ninguém compra produtos feitos em série','a eliminação do lucro, pois a cultura passa a ser gratuita e coletiva'], 1, 'Para os frankfurtianos, a cultura transformada em mercadoria é padronizada para vender, o que molda o gosto e favorece a conformação. A ideia de criatividade irrestrita contraria a produção em série; a indústria cultural gera um mercado enorme, não o fim; e é movida por lucro, não por gratuidade.', 'dificil', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-hum-025', 'sociologia', 'sociologia.Cultura e etnocentrismo', array['enem','vestibular'], 'pt-BR', 'Um turista considera ''estranhos'' e ''inferiores'' os costumes alimentares de outro povo apenas porque diferem dos seus. Essa atitude é exemplo de', array['relativismo cultural, que compreende práticas dentro de seu contexto','diversidade cultural, que reconhece múltiplos modos de viver','aculturação, que mistura traços de culturas em contato prolongado','etnocentrismo, que julga outras culturas pelos valores da própria'], 3, 'Etnocentrismo é tomar a própria cultura como padrão e julgar as demais como inferiores. O relativismo cultural faz o oposto, ao interpretar práticas em seu contexto; diversidade cultural é a existência de variados modos de vida; e aculturação é o contato que modifica traços culturais, não um julgamento de valor.', 'facil', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-hum-026', 'atualidades', 'atualidades.Organizações internacionais', array['enem','vestibular','concurso'], 'pt-BR', 'O Conselho de Segurança da ONU tem cinco membros permanentes com direito de veto. Na prática, esse mecanismo significa que', array['qualquer país da ONU pode, sozinho, cancelar resoluções já aprovadas pelo Conselho, mesmo sem apoio de outros membros do órgão','a rejeição de qualquer dos cinco membros permanentes impede a aprovação de uma resolução substantiva','as decisões dependem apenas da vontade do Secretário-Geral, que pode vetar propostas','os membros não permanentes têm poder de veto, mas os permanentes não'], 1, 'O veto dos cinco permanentes (Estados Unidos, Rússia, China, França e Reino Unido) permite barrar resoluções substantivas, o que explica críticas ao desenho do órgão. Um país qualquer não cancela resoluções já aprovadas; o Secretário-Geral não possui veto; e é o inverso: o veto pertence aos permanentes, não aos rotativos.', 'medio', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', '2026-11-27'::date, '2027-05-26'::date from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-hum-027', 'atualidades', 'atualidades.Integração regional', array['enem','vestibular','concurso'], 'pt-BR', 'O Mercosul foi criado pelo Tratado de Assunção, de 1991, tendo como Estados fundadores', array['Brasil, Chile, Colômbia, Peru e Bolívia','Argentina, Bolívia, Equador e México','Argentina, Brasil, Paraguai e Uruguai','Brasil, Venezuela, Cuba e Panamá'], 2, 'O Tratado de Assunção, de 1991, uniu Argentina, Brasil, Paraguai e Uruguai em um bloco econômico sul-americano com livre circulação de bens e uma tarifa externa comum. Os demais conjuntos misturam países que não foram fundadores, alguns associados ou de outras regiões, como México e Panamá.', 'facil', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', '2026-11-27'::date, '2027-05-26'::date from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-hum-028', 'atualidades', 'atualidades.Meio ambiente e clima', array['enem','vestibular','concurso'], 'pt-BR', 'O Acordo de Paris, adotado em 2015, tem como objetivo central de temperatura', array['manter o aumento da temperatura global bem abaixo de 2 °C em relação ao período pré-industrial, buscando limitá-lo a 1,5 °C','elevar em 5 °C a temperatura média global até o final do século para estimular a agricultura','congelar o consumo de petróleo em todos os países, com sanções imediatas aos que o descumprirem','eliminar em um ano toda a emissão de gases de efeito estufa de qualquer país signatário, sem exceção para países em desenvolvimento nem prazos de transição'], 0, 'O acordo estabelece manter o aquecimento bem abaixo de 2 °C e esforçar-se para 1,5 °C, com metas nacionais voluntárias. Elevar a temperatura é o oposto do objetivo; o acordo não congela o consumo de petróleo nem prevê sanções automáticas; e não exige eliminar emissões em um ano, o que seria inviável.', 'medio', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', '2026-11-27'::date, '2027-05-26'::date from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-hum-030', 'atualidades', 'atualidades.Direitos e tecnologia', array['enem','vestibular','concurso'], 'pt-BR', 'A Lei Geral de Proteção de Dados Pessoais (Lei nº 13.709/2018) distingue dados pessoais e dados pessoais sensíveis. São exemplos de dados sensíveis aqueles sobre', array['apenas o nome completo e o número do telefone usados em cadastros comerciais','somente o modelo do aparelho celular usado e o horário de acesso a um aplicativo e a duração de cada sessão','origem racial ou étnica, convicção religiosa e dado referente à saúde ou à vida sexual','exclusivamente o endereço do imóvel e o valor pago em contas de consumo'], 2, 'A LGPD define dado pessoal sensível como o dado sobre origem racial ou étnica, convicção religiosa, opinião política, filiação sindical, saúde, vida sexual, genético ou biométrico, que exige proteção reforçada por seu potencial discriminatório. Nome e telefone, modelo do aparelho e endereço são dados pessoais comuns, não sensíveis nessa classificação.', 'dificil', '{"origin": "autoral", "refs": [{"citacao": "art. 5º, I e II, Lei 13.709/2018", "fonte": "planalto-lgpd"}]}'::jsonb, 'publicavel', '2026-11-27'::date, '2027-05-26'::date from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-ling-001', 'portugues', 'portugues.Concordância verbal', array['enem','vestibular','concurso'], 'pt-BR', 'Assinale a alternativa em que a concordância verbal está de acordo com a norma-padrão.', array['Fazem dois anos que a biblioteca do bairro foi reformada pela prefeitura.','Devem haver soluções simples para o problema das filas nos postos de saúde.','Houveram muitas reclamações sobre o atraso dos ônibus na avenida central.','Faz dois anos que a biblioteca do bairro foi reformada pela prefeitura.'], 3, 'Gabarito D: O verbo fazer, indicando tempo decorrido, é impessoal e fica na 3ª pessoa do singular: "Faz dois anos". Por que as demais estão erradas: A) "dois anos" não é sujeito; fazer indicando tempo é impessoal e não vai ao plural. B) haver com sentido de existir é impessoal e o auxiliar também fica no singular: "Deve haver". C) haver no sentido de existir é impessoal; o correto é "Houve muitas reclamações".', 'facil', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-ling-002', 'portugues', 'portugues.Concordância nominal', array['enem','vestibular','concurso'], 'pt-BR', 'Segundo a norma-padrão, assinale a frase em que a concordância nominal está correta.', array['Seguem anexas as planilhas solicitadas pela diretoria financeira.','Era proibido a entrada de menores desacompanhados no salão de festas.','Ela chegou meia cansada ao final da maratona de domingo passado.','Obrigada, disse o rapaz ao receber o presente das colegas de turma.'], 0, 'Gabarito A: "Anexo" é adjetivo e concorda com o substantivo a que se refere: planilhas, logo "anexas". Por que as demais estão erradas: B) com artigo ("a entrada"), "proibido" concorda com o substantivo: "proibida". C) "meio", advérbio com sentido de "um pouco", é invariável: "meio cansada". D) "obrigado" concorda com quem agradece; sendo um rapaz, o correto é "obrigado".', 'facil', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-ling-003', 'portugues', 'portugues.Regência verbal', array['enem','vestibular','concurso'], 'pt-BR', 'De acordo com a norma-padrão, a regência verbal está correta em:', array['Prefiro estudar de manhã do que passar a noite acordado diante dos livros.','Ela aspirava o cargo de gerente desde os tempos de estágio na empresa.','Os alunos assistiram ao documentário sobre as geleiras da Patagônia.','Esqueci-me o guarda-chuva em casa e acabei molhado na volta do trabalho.'], 2, 'Gabarito C: No sentido de ver, "assistir" é transitivo indireto e exige a preposição "a": "assistiram ao documentário". Por que as demais estão erradas: A) "preferir" exige "a" e não admite "do que": "prefiro estudar de manhã a passar...". B) "aspirar" no sentido de desejar é transitivo indireto: "aspirava ao cargo". D) esquecer pronominal pede "de": "esqueci-me do guarda-chuva"; sem pronome seria "esqueci o guarda-chuva".', 'medio', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-ling-004', 'portugues', 'portugues.Regência nominal', array['enem','vestibular','concurso'], 'pt-BR', 'Assinale a alternativa em que a regência nominal está de acordo com a norma-padrão.', array['Ela sempre foi muito apegada com os primos mais novos desde a infância.','Ele demonstrou grande aversão a discussões sem propósito durante a reunião.','O gerente tem grande respeito de seus funcionários mais antigos na loja.','Sua dedicação com a pesquisa de campo surpreendeu todos os colegas de turma.'], 1, 'Gabarito B: O substantivo "aversão" rege a preposição "a" (também admite "por"/"para com"): "aversão a discussões". Por que as demais estão erradas: A) "apegado" rege "a": "apegada aos primos". C) "respeito" rege "a", "por" ou "para com", não "de": "respeito por seus funcionários". D) "dedicação" rege "a": "dedicação à pesquisa".', 'medio', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-ling-005', 'portugues', 'portugues.Crase', array['enem','vestibular','concurso'], 'pt-BR', 'Assinale a frase em que o uso do sinal indicativo de crase está correto.', array['Fomos à pé até o mercado central, porque o ônibus estava muito lotado.','Entregamos o relatório à diretora antes do meio-dia, como combinado.','Os dois rivais ficaram frente à frente no centro da quadra de basquete.','Refiro-me à aquele episódio antigo, que ninguém na família quis comentar.'], 1, 'Gabarito B: Há fusão da preposição "a" (entregar a alguém) com o artigo "a" de "a diretora": crase obrigatória. Por que as demais estão erradas: A) antes de palavra masculina ("pé") não há artigo feminino; não ocorre crase: "a pé". C) em expressões formadas por palavras repetidas não há crase: "frente a frente". D) "a" preposição diante de "aquele" (pronome demonstrativo) não leva crase: "a aquele" ou "àquele".', 'medio', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-ling-006', 'portugues', 'portugues.Gramática', array['enem','vestibular','concurso'], 'pt-BR', 'Assinale a alternativa em que a vírgula foi empregada corretamente.', array['Os estudantes, saíram em silêncio para o pátio quando o sinal tocou.','O prefeito anunciou, que a nova praça será entregue à população em maio.','A professora trouxe, livros, revistas e jornais para a aula de leitura.','Quando o sinal tocou, os estudantes saíram em silêncio para o pátio.'], 3, 'Gabarito D: A oração adverbial antecipada ("Quando o sinal tocou") é separada por vírgula da oração principal. Por que as demais estão erradas: A) não se separa o sujeito ("Os estudantes") do verbo com vírgula isolada. B) não se separa o verbo da oração subordinada substantiva que funciona como objeto direto. C) a primeira vírgula separa o verbo de seu objeto; só os itens da enumeração se separam entre si.', 'facil', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-ling-007', 'portugues', 'portugues.Coesão e coerência textual', array['enem','vestibular','concurso'], 'pt-BR', 'Leia: "O rio estava visivelmente poluído; ______, os moradores continuaram pescando nele." Assinale o conectivo que completa o trecho de modo coerente.', array['ainda assim','por isso','ou seja','além disso'], 0, 'Gabarito A: a segunda oração contraria a expectativa criada pela primeira; é preciso um conectivo de oposição/concessão, como "ainda assim". Por que as demais estão erradas: B) indica consequência, mas continuar pescando não é consequência da poluição. C) introduz explicação ou reformulação, o que não ocorre aqui. D) soma argumentos de mesma direção, mas aqui há contraste.', 'medio', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-ling-008', 'portugues', 'portugues.Inferência', array['enem','vestibular','concurso'], 'pt-BR', 'Aviso fixado na portaria de um prédio: "O elevador está em manutenção desde segunda-feira. Pedimos paciência e desejamos boa saúde nas escadas." O trecho final do aviso permite inferir que o autor', array['ameaça os moradores que reclamarem do tempo de duração do conserto.','recomenda a prática de exercícios físicos como solução permanente.','atribui aos próprios moradores a culpa pelo defeito no equipamento.','suaviza o incômodo da interdição com um tom bem-humorado dirigido aos moradores.'], 3, 'Gabarito D: "boa saúde nas escadas" é comentário irônico e leve; o humor busca amenizar a insatisfação, sem negar o problema. Por que as demais estão erradas: A) nada no aviso indica ameaça; o tom é cordial. B) a frase é brincadeira ligada à situação temporária, não recomendação de saúde. C) o texto não menciona culpados; informa a manutenção e pede paciência.', 'dificil', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-ling-009', 'portugues', 'portugues.Fato × opinião', array['enem','vestibular','concurso'], 'pt-BR', 'Assinale a alternativa que expressa uma opinião, e não um fato.', array['A nova linha de ônibus liga o centro ao bairro industrial em 35 minutos.','A nova linha de ônibus começou a funcionar na primeira semana de março.','A nova linha de ônibus é a melhor solução que a cidade poderia ter adotado.','A nova linha de ônibus passa por doze pontos de parada ao longo do trajeto.'], 2, 'Gabarito C: "melhor solução" é um julgamento de valor, que depende do ponto de vista e não pode ser comprovado objetivamente. Por que as demais estão erradas: A) dado mensurável e verificável: é um fato. B) informação de data, verificável: fato. D) contagem verificável: fato.', 'facil', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-ling-010', 'portugues', 'portugues.Semântica', array['enem','vestibular','concurso'], 'pt-BR', 'Complete: "A polícia combateu o ______ de drogas na região, e a prefeitura reorganizou o ______ de veículos na avenida principal."', array['tráfico ... tráfego','tráfego ... tráfico','tráfico ... tráfico','tráfego ... tráfego'], 0, 'Gabarito A: "tráfico" é comércio ilegal; "tráfego" é movimento de veículos ou pessoas. São parônimos, não sinônimos. Por que as demais estão erradas: B) inverte os sentidos: o comércio de drogas é tráfico e o fluxo de veículos é tráfego. C) a segunda lacuna refere-se ao fluxo de veículos, que é "tráfego". D) a primeira lacuna refere-se a comércio ilegal, que é "tráfico".', 'medio', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-ling-011', 'portugues', 'portugues.Ortografia e acentuação', array['enem','vestibular','concurso'], 'pt-BR', 'Assinale a alternativa em que todas as palavras estão grafadas corretamente.', array['exceção, discussão, ascensão','exeção, discussão, ascensão','exceção, discução, ascensão','exceção, discussão, assenção'], 0, 'Gabarito A: as três seguem a grafia correta: exceção (c+ç), discussão (ss) e ascensão (sc). Por que as demais estão erradas: B) "exeção" está errada; o certo é "exceção". C) "discução" está errada; o certo é "discussão". D) "assenção" está errada; o certo é "ascensão".', 'dificil', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-ling-012', 'portugues', 'portugues.Sintaxe', array['enem','vestibular','concurso'], 'pt-BR', 'Em "Os jurados consideraram brilhante a apresentação da jovem", o termo "brilhante" exerce a função sintática de', array['predicativo do sujeito','adjunto adnominal','predicativo do objeto','complemento nominal'], 2, 'Gabarito C: "a apresentação da jovem" é o objeto direto; "brilhante" atribui a ele uma qualidade por meio do verbo "considerar". Por que as demais estão erradas: A) o sujeito é "Os jurados"; "brilhante" qualifica o objeto, não o sujeito. B) não é adjunto adnominal: a qualificação vem por meio do verbo, formando predicado com o objeto. D) complemento nominal completa o sentido de um nome abstrato e vem com preposição; não é o caso.', 'dificil', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-ling-013', 'literatura', 'literatura.Figuras de linguagem', array['enem','vestibular'], 'pt-BR', 'Leia o verso original: "O relógio da sala bocejou às três da tarde." A figura de linguagem predominante é a', array['antítese, porque se aproximam ideias opostas em um mesmo verso.','hipérbole, porque se exagera a intensidade de um fato descrito.','prosopopeia, porque se atribui ação humana a um objeto.','eufemismo, porque se suaviza uma expressão considerada desagradável.'], 2, 'Gabarito C: "bocejar" é ação humana atribuída a objeto inanimado (o relógio): personificação ou prosopopeia. Por que as demais estão erradas: A) não há palavras de sentidos opostos. B) não há exagero de intensidade, mas atribuição de característica humana. D) não há substituição suavizada de termo duro.', 'facil', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-ling-014', 'literatura', 'literatura.Versificação', array['enem','vestibular'], 'pt-BR', 'Um poema cujos versos têm todos dez sílabas poéticas, mas não apresentam rimas entre si, é formado por versos', array['livres, pois dispensam tanto a rima quanto a métrica regular.','monorrimos, pois todos terminam com o mesmo som final.','redondilhos, pois têm cinco ou sete sílabas poéticas cada.','brancos, pois têm métrica regular e ausência de rima.'], 3, 'Gabarito D: versos brancos são os sem rima, porém com medida regular (aqui, decassílabos). Por que as demais estão erradas: A) versos livres não têm métrica fixa; aqui a medida é regular. B) monorrimo exige rima única, e o poema não tem rimas. C) redondilhas têm cinco ou sete sílabas; os versos aqui têm dez.', 'medio', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-ling-015', 'literatura', 'literatura.Realismo e Machado de Assis', array['enem','vestibular'], 'pt-BR', 'Em "Memórias Póstumas de Brás Cubas", de Machado de Assis, o narrador é um defunto que conta a própria vida. Essa escolha narrativa contribui para', array['permitir um olhar irônico e sem pudores sobre os costumes da época.','reforçar a idealização romântica do herói e de seu amor impossível.','apresentar uma explicação científica e determinista para os vícios humanos.','garantir narração objetiva, impessoal e livre de qualquer subjetividade.'], 0, 'Gabarito A: sem os constrangimentos sociais da vida, o narrador pode julgar com franqueza e ironia hábitos e valores. Por que as demais estão erradas: B) o romance é de crítica e ironia realistas, não de idealização romântica. C) tese determinista é característica do Naturalismo, não do recurso do narrador defunto. D) o narrador é pessoal, subjetivo e digressivo; está longe da impessoalidade.', 'medio', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-ling-016', 'literatura', 'literatura.Poesia romântica', array['enem','vestibular'], 'pt-BR', 'A "Canção do Exílio", de Gonçalves Dias, é associada à primeira geração romântica brasileira porque', array['denuncia a escravidão com linguagem social e tom de forte oratória.','expressa o tédio da vida e o fascínio pela morte e pelo sobrenatural.','descreve a realidade urbana com precisão científica e distanciamento.','exalta a natureza e a pátria, vistas com saudade por quem está longe.'], 3, 'Gabarito D: nacionalismo, exaltação da natureza e saudade da terra são traços centrais da primeira geração romântica. Por que as demais estão erradas: A) é característica da poesia condoreira, da terceira geração. B) traços da segunda geração (ultrarromântica). C) pertence ao Realismo e ao Naturalismo, posteriores ao Romantismo.', 'facil', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-ling-017', 'literatura', 'literatura.Semana de 22 e primeira geração', array['enem','vestibular'], 'pt-BR', 'No Manifesto Antropófago, Oswald de Andrade propõe "devorar" as influências estrangeiras. Essa metáfora defende que a cultura brasileira deve', array['recusar por completo qualquer contato com ideias e técnicas estrangeiras.','copiar fielmente os modelos europeus para alcançar o mesmo prestígio.','assimilar criticamente o que vem de fora e recriá-lo como algo próprio.','retornar ao indianismo idealizado do Romantismo do século XIX.'], 2, 'Gabarito C: a antropofagia cultural é digestão crítica: absorver referências externas e recriá-las com identidade nacional. Por que as demais estão erradas: A) a proposta não é isolamento; rejeita a imitação, mas aceita o diálogo transformador. B) a metáfora critica justamente a cópia servil. D) o Modernismo antropofágico faz releitura crítica; não retoma o ideal romântico do índio herói.', 'dificil', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-ling-018', 'ingles', 'ingles.Phrasal verbs', array['enem','vestibular','concurso'], 'en', 'Read: "The outdoor concert was called off because of the storm." In this sentence, "called off" means', array['postponed','confirmed','advertised','cancelled'], 3, 'Gabarito D: "call off" means to cancel an event that was planned. Por que as demais estão erradas: A) "postponed" would be "put off"; "call off" is a definitive cancellation. B) "confirmed" is the opposite idea of cancelling. C) "advertised" has nothing to do with the phrasal verb.', 'facil', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-ling-019', 'ingles', 'ingles.Verbos modais', array['enem','vestibular','concurso'], 'en', 'Choose the best option to complete the sentence: "You ______ wear a helmet when riding a motorbike; it is the law."', array['might','must','may','would'], 1, 'Gabarito B: "must" expresses obligation, appropriate for a legal requirement. Por que as demais estão erradas: A) "might" expresses a weak possibility, not obligation. C) "may" expresses permission or possibility, which does not fit a legal requirement. D) "would" is used for hypotheses or polite requests, not obligation.', 'facil', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-ling-020', 'ingles', 'ingles.Tempos verbais', array['enem','vestibular','concurso'], 'en', 'Choose the correct option: "By the time we arrived at the cinema, the film ______."', array['has already started','already starts','will already start','had already started'], 3, 'Gabarito D: the past perfect indicates an action completed before another past action (our arrival). Por que as demais estão erradas: A) the present perfect cannot combine with "by the time we arrived" (past). B) the present simple does not fit a past context. C) the future does not fit "arrived" (past).', 'medio', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-ling-022', 'ingles', 'ingles.Cognatos e falsos cognatos', array['enem','vestibular','concurso'], 'en', 'Read: "I thought the exam would be easy. Actually, it was quite hard." In this text, "actually" is closest in meaning to', array['currently','recently','in fact','eventually'], 2, 'Gabarito C: "actually" is a false cognate: it introduces a contrast with reality, meaning "in fact". Por que as demais estão erradas: A) "currently" corresponds to "atualmente"; the false-cognate trap. B) "recently" means "recentemente", unrelated to "actually". D) "eventually" means "por fim", another false cognate.', 'medio', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-ling-024', 'ingles', 'ingles.Referência pronominal', array['enem','vestibular','concurso'], 'en', 'Read: "The city installed new bike lanes last year. Residents say they have made commuting safer, although some drivers complain about them." In "they have made commuting safer", the word "they" refers to', array['the residents','some drivers','the new bike lanes','the city'], 2, 'Gabarito C: the lanes are what made commuting safer; "them" at the end also refers to them. Por que as demais estão erradas: A) "residents" is the subject of "say"; they do not make commuting safer. B) drivers appear in the final clause as complainers. D) "city" is singular and would be "it".', 'dificil', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-ling-025', 'espanhol', 'espanhol.Ser e estar', array['enem','vestibular'], 'es', 'Elige la opción correcta: "La sopa ______ fría; ¿puedes calentarla, por favor?"', array['está','es','fue','son'], 0, 'Gabarito A: "estar" expresa un estado o condición transitoria, como la temperatura de la sopa. Por que as demais estão erradas: B) "ser" expresa características permanentes. C) "fue" es pasado de ser/ir y no corresponde al presente de la oración. D) "son" es plural y la sopa es singular.', 'medio', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-ling-026', 'espanhol', 'espanhol.Falsos amigos com o português', array['enem','vestibular'], 'es', 'Lee: "Ana está embarazada y espera un bebé para mayo." En este texto, "embarazada" significa', array['envergonhada','grávida','cansada','doente'], 1, 'Gabarito B: "embarazada" es falso amigo: significa "grávida". Por que as demais estão erradas: A) falso amigo del portugués: "avergonzada" sería la correcta. C) no tiene relación con el sentido del texto. D) la frase habla de un bebé, no de enfermedad.', 'facil', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-ling-027', 'espanhol', 'espanhol.Pretérito perfeito simples e composto', array['enem','vestibular'], 'es', 'Elige la opción correcta: "Ayer ______ al mercado y compré frutas frescas."', array['he ido','voy','fui','iré'], 2, 'Gabarito C: "ayer" indica tiempo concluido y se usa el pretérito indefinido: "fui". Por que as demais estão erradas: A) el pretérito perfecto compuesto no se combina con "ayer". B) el presente no concuerda con "compré". D) el futuro contradice "compré".', 'medio', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-ling-028', 'espanhol', 'espanhol.Perífrases verbais', array['enem','vestibular'], 'es', 'En la frase "Acabo de llegar a casa", la perífrasis "acabar de + infinitivo" expresa', array['una obligación que se debe cumplir en el futuro','una intención de realizar la acción más adelante','una acción que se repite con frecuencia','una acción que terminó hace muy poco tiempo'], 3, 'Gabarito D: "acabar de + infinitivo" indica acción recién terminada. Por que as demais estão erradas: A) la obligación se expresa con "tener que" o "deber". B) la intención se expresa con "ir a + infinitivo". C) la repetición se expresa con "soler".', 'dificil', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-ling-029', 'espanhol', 'espanhol.Comparativo e superlativo', array['enem','vestibular'], 'es', 'Elige la opción correcta: "Este restaurante es muy bueno, pero el de la esquina es ______."', array['mejor','más bueno','muy mejor','más mejor'], 0, 'Gabarito A: "mejor" es el comparativo irregular de "bueno". Por que as demais estão erradas: B) "más bueno" es incorrecto; se usa "mejor". C) "muy" no se combina con "mejor"; se dice "mucho mejor". D) "más mejor" es doble comparativo, incorrecto.', 'medio', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-ling-030', 'artes', 'artes.Impressionismo', array['enem','vestibular'], 'pt-BR', 'Uma característica central da pintura impressionista é', array['reproduzir cenas mitológicas com contornos nítidos e acabamento liso.','registrar efeitos de luz e cor de um instante, em pinceladas rápidas.','representar emoções internas por meio de formas distorcidas e cores arbitrárias.','decompor objetos em formas geométricas vistas de vários ângulos.'], 1, 'Gabarito B: os impressionistas buscavam captar impressões momentâneas de luz e cor. Por que as demais estão erradas: A) característica da pintura acadêmica e neoclássica. C) refere-se ao Expressionismo. D) refere-se ao Cubismo.', 'medio', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-ling-031', 'artes', 'artes.Elementos da música', array['enem','vestibular'], 'pt-BR', 'Na música, a propriedade do som que permite distinguir um som grave de um som agudo é a', array['intensidade','timbre','altura','duração'], 2, 'Gabarito C: altura depende da frequência da onda sonora. Por que as demais estão erradas: A) é o volume (forte ou fraco). B) distingue a "cor" do som de cada fonte. D) é o tempo de permanência do som.', 'facil', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-ling-032', 'artes', 'artes.Patrimônio cultural e preservação', array['enem','vestibular'], 'pt-BR', 'No Brasil, o tombamento de um bem cultural tem como finalidade principal', array['evitar a destruição ou a descaracterização do bem, preservando seu valor.','transferir obrigatoriamente a propriedade do bem para o poder público.','proibir qualquer visitação ao bem para garantir a sua conservação.','congelar o valor de mercado do bem para evitar a especulação.'], 0, 'Gabarito A: o tombamento protege bens de valor histórico, artístico ou cultural; o proprietário mantém a posse. Por que as demais estão erradas: B) o tombamento não transfere a propriedade. C) não proíbe visitação; restringe alterações. D) a finalidade é preservação, não controle de preço.', 'dificil', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-ling-033', 'artes', 'artes.Linguagem cinematográfica', array['enem','vestibular'], 'pt-BR', 'No cinema, o enquadramento que mostra apenas o rosto de um personagem, destacando suas emoções, é chamado de', array['plano geral','plano americano','plano-sequência','close-up (primeiríssimo plano)'], 3, 'Gabarito D: close-up enquadra o rosto, enfatizando expressões. Por que as demais estão erradas: A) mostra o ambiente amplo. B) enquadra o personagem da cabeça aos joelhos. C) refere-se à duração, sem corte.', 'facil', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-ling-034', 'educacao_fisica', 'educacao_fisica.Capacidades físicas', array['enem','vestibular'], 'pt-BR', 'Uma pessoa consegue correr 5 km em ritmo moderado, sem fadiga excessiva. A capacidade física mais envolvida é a', array['força máxima','resistência aeróbia','velocidade de reação','flexibilidade'], 1, 'Gabarito B: é a capacidade de manter esforço prolongado de intensidade moderada. Por que as demais estão erradas: A) é a maior tensão em uma única contração. C) é o tempo de resposta a um estímulo. D) é a amplitude de movimento das articulações.', 'facil', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-ling-035', 'educacao_fisica', 'educacao_fisica.Esporte paralímpico e inclusão', array['enem','vestibular'], 'pt-BR', 'No goalball, esporte paralímpico para pessoas com deficiência visual, todos os atletas usam vendas. A razão dessa regra é', array['aumentar a dificuldade do jogo para torná-lo mais espetacular ao público.','igualar as condições entre atletas com graus diferentes de deficiência visual.','proteger os olhos dos atletas contra o impacto direto da bola pesada.','permitir que atletas sem deficiência também participem das partidas.'], 1, 'Gabarito B: a venda garante equidade entre graus distintos. Por que as demais estão erradas: A) a regra é para equidade, não espetáculo. C) a finalidade principal é igualar condições. D) a modalidade é para pessoas com deficiência visual.', 'medio', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-mat-001', 'matematica', 'matematica.Razão, proporção e porcentagem', array['enem','concurso'], 'pt-BR', 'Uma receita usa 3 xícaras de farinha para fazer 8 bolinhos. Mantendo a mesma proporção, quantas xícaras de farinha são necessárias para fazer 36 bolinhos?', array['13,5 xícaras','12,0 xícaras','4,5 xícaras','31,0 xícaras'], 0, 'A quantidade de farinha é diretamente proporcional ao número de bolinhos: 3/8 = x/36, logo x = 36·3/8 = 13,5 xícaras. Confira sempre a unidade e a interpretação do enunciado antes de escolher. Por que as demais estão erradas: 12,0 xícaras resulta de dividir 36 por 3, ignorando a proporção com os 8 bolinhos; 4,5 xícaras é só 36/8, esquecendo de multiplicar pelas 3 xícaras; 31,0 xícaras vem de raciocínio aditivo (somar a diferença 28 a 3), que não conserva a proporção.', 'facil', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-mat-002', 'matematica', 'matematica.Equações', array['enem','vestibular','concurso'], 'pt-BR', 'Um terreno retangular tem perímetro de 34 m e área de 60 m². Qual é a medida, em metros, do maior lado desse terreno?', array['5 m','12 m','17 m','8 m'], 1, 'Com lados x e y: x+y=17 e xy=60. Substituindo, x²-17x+60=0, cujas raízes são 5 e 12. O maior lado mede 12 m. Confira sempre a unidade e a interpretação do enunciado antes de escolher. Por que as demais estão erradas: 5 m é o menor lado, a outra raiz da equação; 17 m é o semiperímetro (x+y), não um lado isolado; 8 m é aproximadamente a média dos lados, que não resolve o sistema.', 'medio', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-mat-003', 'matematica', 'matematica.Funções', array['enem','vestibular'], 'pt-BR', 'Uma função afim f(x) = ax + b satisfaz f(2) = 7 e f(5) = 16. Quanto vale f(10)?', array['30','32','31','33'], 2, 'Da diferença f(5)-f(2) = 3a = 9 obtém-se a = 3, e b = 7-6 = 1. Logo f(10) = 3·10+1 = 31. Confira sempre a unidade e a interpretação do enunciado antes de escolher. Por que as demais estão erradas: 30 esquece o coeficiente linear b; 32 supõe proporcionalidade direta (f(10)=2·f(5)), válida só para b=0; 33 usa x+1 no lugar de x, calculando a·10+3.', 'medio', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-mat-004', 'matematica', 'matematica.Sequências e progressões', array['enem','vestibular','concurso'], 'pt-BR', 'Em uma progressão aritmética, o primeiro termo é 5 e a razão é 4. Qual é a soma dos 20 primeiros termos?', array['1720','900','810','860'], 3, 'O 20º termo é 5+19·4 = 81. A soma é (5+81)·20/2 = 860. Confira sempre a unidade e a interpretação do enunciado antes de escolher. Por que as demais estão erradas: 1720 esquece de dividir por 2 na fórmula da soma; 900 usa a20=85 (20 razões em vez de 19); 810 calcula (81·20)/2 e omite o primeiro termo na média.', 'medio', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-mat-006', 'matematica', 'matematica.Geometria plana', array['enem','vestibular','concurso'], 'pt-BR', 'Um canteiro circular tem raio de 7 m. Usando π = 3,14, qual é a área do canteiro, em m²?', array['43,96 m²','153,86 m²','615,44 m²','49,00 m²'], 1, 'A = πr² = 3,14·49 = 153,86 m². Confira sempre a unidade e a interpretação do enunciado antes de escolher. Por que as demais estão erradas: 43,96 m² é o comprimento 2πr, não a área; 615,44 m² usa o diâmetro (14) no lugar do raio; 49,00 m² calcula só r², esquecendo π.', 'facil', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-mat-007', 'matematica', 'matematica.Geometria espacial', array['enem','vestibular'], 'pt-BR', 'Um reservatório cilíndrico tem raio da base de 3 m e altura de 10 m. Usando π = 3,14, qual é o seu volume, em m³?', array['94,20 m³','188,40 m³','282,60 m³','847,80 m³'], 2, 'V = πr²h = 3,14·9·10 = 282,6 m³. Confira sempre a unidade e a interpretação do enunciado antes de escolher. Por que as demais estão erradas: 94,20 m³ é πrh, sem elevar r ao quadrado; 188,40 m³ é a área lateral 2πrh, não o volume; 847,80 m³ eleva r ao cubo (27) no lugar de r².', 'medio', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-mat-008', 'matematica', 'matematica.Trigonometria', array['enem','vestibular'], 'pt-BR', 'Uma escada de 5 m está apoiada em uma parede e forma 30° com o chão. Considerando sen 30° = 0,5, cos 30° ≈ 0,87 e tg 30° ≈ 0,58, a que altura da parede, em metros, está o topo da escada?', array['4,35 m','2,90 m','10,00 m','2,50 m'], 3, 'A altura é o cateto oposto ao ângulo: h = 5·sen 30° = 2,5 m. Confira sempre a unidade e a interpretação do enunciado antes de escolher. Por que as demais estão erradas: 4,35 m usa o cosseno, que dá a distância da base da escada à parede; 2,90 m usa a tangente, que relaciona os catetos, não a hipotenusa; 10,00 m divide 5 pelo seno, invertendo a relação.', 'medio', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-mat-009', 'matematica', 'matematica.Probabilidade', array['enem','vestibular','concurso'], 'pt-BR', 'Dois dados comuns e honestos são lançados. Qual é a probabilidade de a soma dos resultados ser igual a 8?', array['5/36','1/6','1/9','1/8'], 0, 'Os pares com soma 8 são (2,6),(3,5),(4,4),(5,3),(6,2): 5 casos em 36, ou seja, 5/36. Confira sempre a unidade e a interpretação do enunciado antes de escolher. Por que as demais estão erradas: 1/6 corresponde a 6 casos favoráveis (soma 7); 1/9 corresponde a apenas 4 casos, omitindo um par; 1/8 divide por 8, o valor da soma, e não pelo total 36.', 'medio', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-mat-011', 'matematica', 'matematica.Geometria analítica', array['enem','vestibular','concurso'], 'pt-BR', 'No plano cartesiano, os pontos A(1, 2) e B(7, 10) são extremos de um segmento. Qual é a medida desse segmento, em unidades?', array['14','100','10','6'], 2, 'd = √[(7-1)²+(10-2)²] = √(36+64) = 10. Confira sempre a unidade e a interpretação do enunciado antes de escolher. Por que as demais estão erradas: 14 soma as diferenças (6+8), sem usar Pitágoras; 100 esquece a raiz quadrada, dando d²; 6 é apenas a diferença das abscissas.', 'medio', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-mat-012', 'matematica', 'matematica.Inequações', array['enem','vestibular','concurso'], 'pt-BR', 'Quantos números inteiros x satisfazem a inequação x² - 5x - 14 < 0?', array['10','7','9','8'], 3, 'As raízes são -2 e 7; a parábola é negativa entre elas, estritamente. Os inteiros são -1, 0, ..., 6: 8 valores. Confira sempre a unidade e a interpretação do enunciado antes de escolher. Por que as demais estão erradas: 10 inclui as duas raízes (-2 e 7), mas a desigualdade é estrita; 7 conta de 0 a 6, esquecendo -1; 9 inclui o 7, que anula a expressão.', 'dificil', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-mat-013', 'raciocinio_logico', 'raciocinio_logico.tabela_verdade', array['concurso'], 'pt-BR', 'Na tabela-verdade da proposição (p ∧ q) → r, com três proposições simples, em quantas das 8 linhas o valor lógico é verdadeiro?', array['4','7','6','8'], 1, 'A condicional só é falsa quando o antecedente é V e o consequente é F: p=V, q=V, r=F (1 linha). Logo são 7 linhas verdadeiras. Confira sempre a unidade e a interpretação do enunciado antes de escolher. Por que as demais estão erradas: 4 conta apenas as linhas em que r é verdadeiro; 6 descarta duas linhas de antecedente falso; 8 supõe que a condicional é sempre verdadeira.', 'facil', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-mat-014', 'raciocinio_logico', 'raciocinio_logico.proposicoes_conectivos', array['concurso'], 'pt-BR', 'Sabe-se que p é verdadeira, q é falsa e r é verdadeira. Qual das proposições compostas abaixo é verdadeira?', array['(p ∧ q) ∨ (¬p ∧ r)','(p → q) ∨ ¬r','(q → r) ∧ p','p ↔ q'], 2, 'Com p=V, q=F, r=V: (q→r) é V (antecedente falso) e p é V, então a conjunção é V. Confira sempre a unidade e a interpretação do enunciado antes de escolher. Por que as demais estão erradas: (p ∧ q) ∨ (¬p ∧ r) é falsa porque p∧q e ¬p∧r são ambas falsas; (p → q) ∨ ¬r é falsa: p→q é falsa e ¬r também; p ↔ q é falsa: o bicondicional exige valores iguais e p e q diferem.', 'medio', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-mat-015', 'raciocinio_logico', 'raciocinio_logico.tabela_verdade', array['concurso'], 'pt-BR', 'Qual das proposições abaixo é uma tautologia, isto é, tem valor lógico verdadeiro para quaisquer valores de p e q?', array['(p → q) ∧ (q → p)','p → (p ∧ q)','(p ∧ q) → ¬p','(p → q) ∨ (q → p)'], 3, 'Se p→q é falsa (p=V, q=F), então q→p é verdadeira; logo a disjunção nunca é falsa. Confira sempre a unidade e a interpretação do enunciado antes de escolher. Por que as demais estão erradas: (p → q) ∧ (q → p) é um bicondicional, falso quando p e q diferem; p → (p ∧ q) é falsa com p=V e q=F; (p ∧ q) → ¬p é falsa com p=V e q=V.', 'dificil', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-mat-016', 'raciocinio_logico', 'raciocinio_logico.negacao', array['concurso'], 'pt-BR', 'Considere a afirmação: "Se chove, então o jogo é cancelado." Qual das alternativas é a negação lógica dessa afirmação?', array['Chove e o jogo não é cancelado.','Não chove e o jogo é cancelado.','Não chove ou o jogo é cancelado.','Se não chove, o jogo não é cancelado.'], 0, '¬(p→q) ≡ p ∧ ¬q: chove e o jogo não é cancelado. Confira sempre a unidade e a interpretação do enunciado antes de escolher. Por que as demais estão erradas: Não chove e o jogo é cancelado. nega as duas partes e troca o conectivo, o que não é a negação; Não chove ou o jogo é cancelado. equivale à própria condicional original; Se não chove, o jogo não é cancelado. é a inversa da condicional, que não é equivalente à negação.', 'medio', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-mat-017', 'raciocinio_logico', 'raciocinio_logico.negacao', array['concurso'], 'pt-BR', 'Qual é a negação lógica de "Ana viaja ou Bia estuda"?', array['Ana não viaja ou Bia não estuda.','Ana não viaja e Bia não estuda.','Ana viaja e Bia não estuda.','Ana não viaja ou Bia estuda.'], 1, 'Pela lei de De Morgan, ¬(p∨q) ≡ ¬p ∧ ¬q. Confira sempre a unidade e a interpretação do enunciado antes de escolher. Por que as demais estão erradas: Ana não viaja ou Bia não estuda. nega as duas partes mas mantém o ''ou'', erro típico de De Morgan; Ana viaja e Bia não estuda. nega só a segunda parte e troca o conectivo; Ana não viaja ou Bia estuda. mantém a segunda parte afirmada e troca o conectivo.', 'facil', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-mat-019', 'raciocinio_logico', 'raciocinio_logico.diagramas_conjuntos', array['concurso'], 'pt-BR', 'Em um grupo de 120 pessoas, 70 falam inglês, 50 falam espanhol e 20 falam os dois idiomas. Quantas pessoas do grupo não falam nenhum dos dois idiomas?', array['0 pessoas','30 pessoas','50 pessoas','20 pessoas'], 3, '|A∪B| = 70+50-20 = 100, logo 120-100 = 20 não falam nenhum. Confira sempre a unidade e a interpretação do enunciado antes de escolher. Por que as demais estão erradas: 0 pessoas soma 70+50 sem descontar a interseção; 30 pessoas subtrai 70 e 20 do total, ignorando os 50; 50 pessoas subtrai só os 70 que falam inglês.', 'medio', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-mat-020', 'raciocinio_logico', 'raciocinio_logico.sequencias_padroes', array['concurso'], 'pt-BR', 'Observe a sequência: 2, 5, 11, 23, 47, ... Seguindo o mesmo padrão de formação, qual é o próximo termo?', array['95','94','71','96'], 0, 'Cada termo é o dobro do anterior mais 1: 47·2+1 = 95. Confira sempre a unidade e a interpretação do enunciado antes de escolher. Por que as demais estão erradas: 94 é 2·47 sem somar 1; 71 soma 24 (diferença anterior) em vez de 48; 96 dobra e soma 2 em vez de 1.', 'medio', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-mat-021', 'raciocinio_logico', 'raciocinio_logico.analise_combinatoria', array['concurso'], 'pt-BR', 'De quantas maneiras 5 pessoas distintas podem formar uma fila, de modo que duas delas, Ana e Bia, fiquem sempre lado a lado (em qualquer ordem entre si)?', array['120 maneiras','48 maneiras','24 maneiras','96 maneiras'], 1, 'Tratando Ana e Bia como um bloco: 4! = 24 filas, vezes 2 ordens internas = 48. Confira sempre a unidade e a interpretação do enunciado antes de escolher. Por que as demais estão erradas: 120 maneiras é 5!, sem a restrição; 24 maneiras esquece a troca de ordem entre Ana e Bia; 96 maneiras conta 4!·4, errando o número de ordens internas.', 'medio', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-mat-022', 'raciocinio_logico', 'raciocinio_logico.problemas_verdade_mentira', array['concurso'], 'pt-BR', 'Três pessoas, Ana, Bruno e Carla, são suspeitas de ter quebrado um vaso, e apenas uma o fez. Ana diz: "Foi a Carla." Bruno diz: "Não fui eu." Carla diz: "A Ana mente." Sabendo que exatamente uma das três afirmações é verdadeira, quem quebrou o vaso?', array['Ana','Carla','Bruno','Não é possível determinar'], 2, 'Testando cada culpado: se fosse Ana, Bruno e Carla diriam a verdade (2 verdadeiras); se fosse Carla, Ana e Bruno diriam (2); se for Bruno, só a de Carla é verdadeira. Confira sempre a unidade e a interpretação do enunciado antes de escolher. Por que as demais estão erradas: Ana geraria duas afirmações verdadeiras (Bruno e Carla); Carla geraria duas verdadeiras (Ana e Bruno); Não é possível determinar há solução única, portanto é possível determinar.', 'dificil', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-mat-023', 'raciocinio_logico', 'raciocinio_logico.problemas_verdade_mentira', array['concurso'], 'pt-BR', 'Numa ilha, cada habitante ou sempre diz a verdade ou sempre mente. A diz: "B é mentiroso." B diz: "C é mentiroso." C diz: "A e B são mentirosos." Quantos desses três habitantes são mentirosos?', array['0','1','3','2'], 3, 'Se A fosse sincero, B seria mentiroso e C sincero, mas C diria uma falsidade. Logo A mente, B é sincero e C mente: 2 mentirosos. Confira sempre a unidade e a interpretação do enunciado antes de escolher. Por que as demais estão erradas: 0 é impossível, pois C se contradiria; 1 aceita A sincero, o que gera contradição; 3 exige que todos mintam, mas então B diria a verdade.', 'dificil', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-mat-024', 'raciocinio_logico', 'raciocinio_logico.proposicoes_conectivos', array['concurso'], 'pt-BR', 'Na tabela-verdade da proposição (p ∨ q) → (r ∧ ¬p), quantas das 8 linhas têm valor lógico falso?', array['5','3','4','8'], 0, 'Só é verdadeira com p=q=F (2 linhas) ou com p=F, q=V, r=V (1 linha): 3 verdadeiras e 5 falsas. Confira sempre a unidade e a interpretação do enunciado antes de escolher. Por que as demais estão erradas: 3 é o número de linhas verdadeiras; 4 metade das linhas, sem cálculo; 8 supõe todas falsas.', 'medio', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-mat-025', 'matematica_financeira', 'matematica_financeira.porcentagem_variacao', array['concurso','enem'], 'pt-BR', 'O preço de um produto sofreu aumento de 20% e, no mês seguinte, uma redução de 20% sobre o novo preço. Qual foi a variação percentual total em relação ao preço original?', array['0,00%','-2,00%','-4,00%','4,00%'], 2, 'Fator acumulado: 1,2·0,8 = 0,96, ou seja, variação de -4%. Os percentuais incidem sobre bases diferentes. Confira sempre a unidade e a interpretação do enunciado antes de escolher. Por que as demais estão erradas: 0,00% supõe que aumento e redução de mesmo percentual se anulam; -2,00% divide a perda de 4% pela metade, sem base teórica; 4,00% tem o sinal trocado: o preço final é menor que o original.', 'facil', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-mat-026', 'matematica_financeira', 'matematica_financeira.juros_simples', array['concurso','enem'], 'pt-BR', 'Um capital de R$ 3.000,00 é aplicado a juros simples, à taxa de 2% ao mês, durante 8 meses. Qual é o montante, em reais, ao final do período?', array['R$ 3.514,98','R$ 480,00','R$ 3.048,00','R$ 3.480,00'], 3, 'Juros simples: J = 3.000·0,02·8 = 480, e M = C + J = 3.480,00. Confira sempre a unidade e a interpretação do enunciado antes de escolher. Por que as demais estão erradas: R$ 3.514,98 aplica juros compostos, o que o enunciado não pede; R$ 480,00 é apenas o juro, sem somar o capital; R$ 3.048,00 converte 2% em 0,002 em vez de 0,02.', 'facil', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-mat-028', 'matematica_financeira', 'matematica_financeira.descontos', array['concurso','enem'], 'pt-BR', 'Um título de R$ 8.000,00 será pago daqui a 3 meses. Com desconto comercial (por fora) simples de 2% ao mês, qual é o valor atual do título, em reais?', array['R$ 7.547,17','R$ 7.520,00','R$ 480,00','R$ 7.840,00'], 1, 'Desconto comercial: D = 8.000·0,02·3 = 480; valor atual = 8.000-480 = 7.520,00. Confira sempre a unidade e a interpretação do enunciado antes de escolher. Por que as demais estão erradas: R$ 7.547,17 é o desconto racional (por dentro), outro conceito; R$ 480,00 é só o desconto, não o valor atual; R$ 7.840,00 desconta apenas um mês.', 'medio', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-mat-029', 'matematica_financeira', 'matematica_financeira.taxas_equivalentes', array['concurso','enem'], 'pt-BR', 'Qual é a taxa efetiva anual equivalente a uma taxa de 1% ao mês, no regime de juros compostos? Arredonde para duas casas decimais.', array['12,00%','12,75%','12,68%','11,36%'], 2, 'A taxa anual é (1,01)¹² - 1 ≈ 0,1268, ou seja, 12,68% ao ano. Confira sempre a unidade e a interpretação do enunciado antes de escolher. Por que as demais estão erradas: 12,00% multiplica a taxa mensal por 12 (equivalência de juros simples); 12,75% usa capitalização contínua, que não é a do enunciado; 11,36% trata a taxa como desconto mensal (1-0,99¹²).', 'medio', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-mat-030', 'matematica_financeira', 'matematica_financeira.series_pagamentos', array['concurso'], 'pt-BR', 'Um financiamento de R$ 10.000,00 será pago em 6 prestações mensais, iguais e postecipadas (a primeira vence 1 mês após a compra), com juros compostos de 2% ao mês. Qual é o valor aproximado da prestação, em reais?', array['R$ 1.666,67','R$ 1.866,67','R$ 1.750,25','R$ 1.785,26'], 3, 'PMT = PV·i/[1-(1+i)⁻ⁿ] = 10.000·0,02/(1-1,02⁻⁶) ≈ 200/0,112029 = 1.785,26. Confira sempre a unidade e a interpretação do enunciado antes de escolher. Por que as demais estão erradas: R$ 1.666,67 ignora os juros e divide o valor por 6; R$ 1.866,67 soma os juros do 1º mês a todas as prestações; R$ 1.750,25 calcula como se a série fosse antecipada.', 'dificil', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-mat-031', 'matematica_financeira', 'matematica_financeira.sistemas_amortizacao', array['concurso','enem'], 'pt-BR', 'Uma dívida de R$ 12.000,00 será quitada em 12 parcelas mensais pelo Sistema de Amortização Constante (SAC), com juros de 1% ao mês sobre o saldo devedor. Qual é o valor da primeira parcela, em reais?', array['R$ 1.120,00','R$ 1.000,00','R$ 1.066,19','R$ 1.010,00'], 0, 'No SAC, amortização = 12.000/12 = 1.000, e juros do 1º mês = 120; parcela = 1.120,00. Confira sempre a unidade e a interpretação do enunciado antes de escolher. Por que as demais estão erradas: R$ 1.000,00 é só a amortização, sem juros; R$ 1.066,19 é a parcela fixa do sistema Price, outro sistema; R$ 1.010,00 é a última parcela do SAC (juros sobre 1.000).', 'medio', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-mat-032', 'matematica_financeira', 'matematica_financeira.vpl_tir', array['concurso'], 'pt-BR', 'Um projeto exige investimento inicial de R$ 10.000,00 e promete receber R$ 6.000,00 ao fim do 1º ano e R$ 6.000,00 ao fim do 2º ano. Com taxa mínima de atratividade de 10% ao ano, qual é o VPL do projeto, em reais, arredondado ao centavo?', array['R$ 2.000,00','R$ 413,22','R$ 10.413,22','R$ -413,22'], 1, 'VPL = 6.000/1,1 + 6.000/1,21 - 10.000 ≈ 5.454,55 + 4.958,68 - 10.000 = 413,22. Confira sempre a unidade e a interpretação do enunciado antes de escolher. Por que as demais estão erradas: R$ 2.000,00 soma os fluxos sem descontar (12.000-10.000); R$ 10.413,22 é o valor presente das entradas, sem subtrair o investimento; R$ -413,22 tem o sinal trocado, indicando rejeição indevida.', 'dificil', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-mat-033', 'matematica_financeira', 'matematica_financeira.porcentagem_variacao', array['concurso','enem'], 'pt-BR', 'Um produto recebeu desconto de 15% e, em seguida, aumento de 10% sobre o preço já descontado. Qual é a variação percentual total em relação ao preço inicial?', array['-5,00%','6,50%','-6,50%','5,00%'], 2, 'Fator: 0,85·1,10 = 0,935, logo a variação é -6,5%. Confira sempre a unidade e a interpretação do enunciado antes de escolher. Por que as demais estão erradas: -5,00% soma os percentuais (-15+10), ignorando as bases diferentes; 6,50% tem sinal trocado: o preço final é menor que o inicial; 5,00% considera aumento de 5%, erro de soma com sinal invertido.', 'medio', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-mat-034', 'matematica_financeira', 'matematica_financeira.juros_compostos', array['concurso'], 'pt-BR', 'Um capital rende juros compostos de 5% ao mês. Qual é o menor número inteiro de meses necessário para que ele mais do que dobre de valor?', array['14 meses','20 meses','10 meses','15 meses'], 3, 'Procura-se o menor n com 1,05ⁿ > 2: n = ln2/ln1,05 ≈ 14,2; logo, 15 meses (1,05¹⁴ ≈ 1,98 ainda não dobrou). Confira sempre a unidade e a interpretação do enunciado antes de escolher. Por que as demais estão erradas: 14 meses 1,05¹⁴ ≈ 1,98, ainda abaixo de 2; 20 meses é a resposta de juros simples (100/5); 10 meses 1,05¹⁰ ≈ 1,63, longe de dobrar.', 'dificil', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-mat-035', 'estatistica', 'estatistica.media_mediana_moda', array['enem','vestibular','concurso'], 'pt-BR', 'As notas de seis alunos em uma prova, na ordem de correção, foram: 12, 3, 9, 5, 10 e 8. Qual é a mediana dessas notas?', array['7,83','7,00','9,00','8,50'], 3, 'Ordenando: 3, 5, 8, 9, 10, 12. Com 6 valores, a mediana é a média dos centrais: (8+9)/2 = 8,5. Confira sempre a unidade e a interpretação do enunciado antes de escolher. Por que as demais estão erradas: 7,83 é a média aritmética, não a mediana; 7,00 são os dois valores centrais da lista desordenada, sem ordenar; 9,00 é só o 4º valor, sem fazer a média dos dois centrais.', 'facil', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-mat-036', 'estatistica', 'estatistica.media_mediana_moda', array['enem','vestibular','concurso'], 'pt-BR', 'Em uma disciplina, a média final é ponderada: prova 1 (nota 6) tem peso 2, prova 2 (nota 8) tem peso 3 e prova 3 (nota 9) tem peso 5. Qual é a média final?', array['8,10','7,67','8,50','7,50'], 0, 'Média ponderada = (6·2 + 8·3 + 9·5)/(2+3+5) = 81/10 = 8,1. Confira sempre a unidade e a interpretação do enunciado antes de escolher. Por que as demais estão erradas: 7,67 é a média simples, ignorando os pesos; 8,50 é a média de 8 e 9 apenas, desprezando a primeira prova; 7,50 é a média de 6 e 9 apenas.', 'medio', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-mat-037', 'estatistica', 'estatistica.dispersao', array['enem','vestibular','concurso'], 'pt-BR', 'Considere o conjunto de dados 2, 4, 4, 4, 5, 5, 7, 9, tratado como população. Qual é o desvio-padrão populacional?', array['4,00','2,00','2,14','5,00'], 1, 'Média 5; desvios ao quadrado somam 32; variância populacional = 32/8 = 4; desvio-padrão = 2. Confira sempre a unidade e a interpretação do enunciado antes de escolher. Por que as demais estão erradas: 4,00 é a variância, sem extrair a raiz; 2,14 é o desvio-padrão amostral (divisão por n-1); 5,00 é a média, e não uma medida de dispersão.', 'medio', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-mat-038', 'estatistica', 'estatistica.probabilidade_basica', array['enem','vestibular','concurso'], 'pt-BR', 'Uma urna tem 5 bolas azuis, 3 vermelhas e 2 verdes, todas iguais ao tato. Retirando uma bola ao acaso, qual é a probabilidade de ela não ser vermelha?', array['3/10','1/2','7/10','7/3'], 2, 'Há 7 bolas não vermelhas em 10: P = 7/10. Confira sempre a unidade e a interpretação do enunciado antes de escolher. Por que as demais estão erradas: 3/10 é a probabilidade de sair vermelha; 1/2 compara só azuis com as demais, ignorando as verdes; 7/3 é uma razão entre 7 e 3, e não uma probabilidade.', 'facil', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-mat-039', 'estatistica', 'estatistica.probabilidade_condicional', array['enem','vestibular','concurso'], 'pt-BR', 'Em um estudo, P(A) = 0,40, P(B) = 0,50 e P(A ∩ B) = 0,20. Qual é o valor de P(A | B), a probabilidade de A dado B?', array['0,50','0,20','0,70','0,40'], 3, 'P(A|B) = P(A∩B)/P(B) = 0,20/0,50 = 0,40. Confira sempre a unidade e a interpretação do enunciado antes de escolher. Por que as demais estão erradas: 0,50 é P(B|A), com o denominador trocado; 0,20 é P(A∩B), sem dividir por P(B); 0,70 é P(A∪B), outra grandeza.', 'medio', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-mat-040', 'estatistica', 'estatistica.probabilidade_condicional', array['vestibular','concurso'], 'pt-BR', 'Uma doença atinge 2% da população. Um teste dá resultado positivo em 90% dos doentes e em 5% dos não doentes. Para uma pessoa com teste positivo, qual é a probabilidade de realmente ter a doença? Dê o resultado em porcentagem, com uma casa decimal.', array['26,9%','90,0%','6,7%','1,8%'], 0, 'Pelo teorema de Bayes: P(D|+) = 0,018/(0,018+0,049) ≈ 0,269, ou 26,9%. Confira sempre a unidade e a interpretação do enunciado antes de escolher. Por que as demais estão erradas: 90,0% é a sensibilidade, P(+|D), e não a probabilidade pedida; 6,7% é a probabilidade total de um positivo; 1,8% é a de ser doente e testar positivo juntos.', 'dificil', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-mat-043', 'estatistica', 'estatistica.correlacao_regressao', array['vestibular','concurso'], 'pt-BR', 'Os pares (x, y) observados foram (1, 3), (2, 5), (3, 6) e (4, 10). A reta de mínimos quadrados é ŷ = a + b·x. Qual é o valor previsto por essa reta para x = 6?', array['6,00','15,00','14,67','13,70'], 3, 'Com b = 2,2 e a = 0,5, ŷ(6) = 0,5 + 2,2·6 = 13,7. Confira sempre a unidade e a interpretação do enunciado antes de escolher. Por que as demais estão erradas: 6,00 é a média de y, que ignora a relação com x; 15,00 extrapola a razão y/x do último ponto, sem ajuste; 14,67 usa a reta por apenas dois pontos extremos.', 'medio', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-mat-044', 'estatistica', 'estatistica.leitura_graficos', array['enem','vestibular','concurso'], 'pt-BR', 'Uma tabela de frequências de idades de 100 pessoas mostra: 0 a 10 anos: 12 pessoas; 10 a 20 anos: 28 pessoas; 20 a 30 anos: 40 pessoas; 30 a 40 anos: 20 pessoas (cada classe inclui o limite inferior e exclui o superior). Qual é a porcentagem de pessoas com menos de 30 anos?', array['80%','40%','20%','68%'], 0, 'Menos de 30 anos: 12+28+40 = 80 pessoas em 100, ou seja, 80%. Confira sempre a unidade e a interpretação do enunciado antes de escolher. Por que as demais estão erradas: 40% considera só a classe 20 a 30; 20% é a porcentagem da última classe (30 a 40); 68% soma apenas as duas classes centrais (28+40).', 'facil', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-mat-045', 'educacao_financeira', 'educacao_financeira.orcamento', array['enem','concurso'], 'pt-BR', 'Uma família tem renda mensal de R$ 3.200,00, gastos fixos de R$ 1.800,00 e gastos variáveis de R$ 900,00. Ela quer poupar 15% da renda. Depois de poupar, quanto sobra no mês, em reais?', array['R$ 20,00','R$ 500,00','R$ 480,00','R$ 425,00'], 0, 'Sobra antes de poupar: 3.200-1.800-900 = 500. A meta de 15% é 480; após poupar, restam 20,00. Confira sempre a unidade e a interpretação do enunciado antes de escolher. Por que as demais estão erradas: R$ 500,00 é a sobra antes de poupar; R$ 480,00 é o valor da poupança, não o que sobra; R$ 425,00 aplica os 15% sobre a sobra, não sobre a renda.', 'facil', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-mat-046', 'educacao_financeira', 'educacao_financeira.inflacao_poder_compra', array['enem','concurso'], 'pt-BR', 'Suponha uma inflação acumulada de 8% em um ano (valor hipotético, para fins didáticos). Um salário de R$ 4.000,00, sem reajuste, equivale em poder de compra a quanto, em reais do início do ano?', array['R$ 3.680,00','R$ 3.703,70','R$ 3.200,00','R$ 4.320,00'], 1, 'O poder de compra cai pelo fator 1/1,08: 4.000/1,08 ≈ 3.703,70. Confira sempre a unidade e a interpretação do enunciado antes de escolher. Por que as demais estão erradas: R$ 3.680,00 subtrai 8% do salário, em vez de dividir por 1,08; R$ 3.200,00 reduz 20%, sem base no enunciado; R$ 4.320,00 multiplica por 1,08, como se o salário tivesse aumentado.', 'medio', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-mat-047', 'educacao_financeira', 'educacao_financeira.credito_juros', array['enem','concurso'], 'pt-BR', 'Um aparelho custa R$ 1.200,00 à vista, ou 3 parcelas de R$ 420,00. Em termos percentuais, qual é o acréscimo total do parcelamento sobre o preço à vista?', array['4,76%','1,67%','5,00%','35,00%'], 2, 'Total a prazo: 3·420 = 1.260; acréscimo de 60 sobre 1.200 = 5%. Confira sempre a unidade e a interpretação do enunciado antes de escolher. Por que as demais estão erradas: 4,76% divide o acréscimo pelo valor a prazo, mudando a base; 1,67% divide o acréscimo por 3 e por 1.200; 35,00% compara a parcela com o preço à vista.', 'medio', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-mat-048', 'educacao_financeira', 'educacao_financeira.poupanca_investimentos', array['enem','concurso'], 'pt-BR', 'Uma pessoa deposita R$ 200,00 ao fim de cada mês durante 12 meses, em aplicação que rende 1% ao mês (taxa hipotética). Qual é o montante, em reais, imediatamente após o último depósito?', array['R$ 2.400,00','R$ 2.561,87','R$ 2.704,38','R$ 2.536,50'], 3, 'Valor futuro de série postecipada: 200·(1,01¹²-1)/0,01 ≈ 200·12,6825 = 2.536,50. Confira sempre a unidade e a interpretação do enunciado antes de escolher. Por que as demais estão erradas: R$ 2.400,00 soma só os depósitos, sem juros; R$ 2.561,87 supõe depósitos no início de cada mês; R$ 2.704,38 aplica juros de 12 meses sobre todo o total depositado.', 'dificil', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-nat-001', 'biologia', 'biologia.Membrana plasmática', array['enem','vestibular'], 'pt-BR', 'Para conservar carne, uma salmoura muito concentrada em sal era usada antigamente. Ao observar ao microscópio uma célula de bactéria ou de tecido imersa em solução salina muito mais concentrada que o seu citoplasma, o que ocorre com essa célula?', array['Perde água por osmose para o meio externo e murcha, pois o meio é hipertônico em relação a ela','Absorve água do meio por osmose, incha e se rompe, porque o meio externo é hipotônico em relação a ela','Absorve o sal por transporte ativo até igualar as concentrações e continua com o volume inalterado','Não troca água com o meio externo, pois a membrana plasmática é impermeável a água e a solutos'], 0, 'A solução externa é hipertônica em relação ao citoplasma, então a água sai da célula por osmose, atravessando a membrana plasmática semipermeável, e a célula murcha (plasmólise em células com parede, crenação em células animais). Essa perda de água dificulta a vida dos microrganismos, o que explica a conservação. Entrar água e estourar ocorre em meio hipotônico. Entrada de sal por transporte ativo não explica o efeito dominante. A ausência de movimento só ocorreria se os meios fossem isotônicos.', 'facil', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-nat-002', 'biologia', 'biologia.Organelas', array['enem','vestibular'], 'pt-BR', 'Um atleta de resistência treina por meses e, depois, exames de uma biópsia de seus músculos mostram aumento no número de uma organela. Qual organela é essa e qual a função que justifica o aumento?', array['Lisossomo, que digere substâncias dentro da célula e fornece a maior parte da energia necessária à contração','Mitocôndria, que realiza a respiração aeróbia e produz o ATP usado na contração','Complexo golgiense, que empacota proteínas e libera a energia necessária à contração muscular','Ribossomo, que sintetiza proteínas e fornece a maior parte do ATP usado na contração muscular'], 1, 'Treino de resistência exige produção contínua de ATP, e a mitocôndria é a organela da respiração aeróbia, onde o oxigênio é usado para extrair muita energia da glicose e dos ácidos graxos. Por isso músculos treinados têm mais mitocôndrias. Os lisossomos realizam digestão intracelular, não produzem ATP. O complexo golgiense modifica e secreta proteínas. Os ribossomos sintetizam proteínas e não são especializados em fornecer energia.', 'facil', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-nat-003', 'biologia', 'biologia.Ciclo celular, mitose e meiose', array['enem','vestibular'], 'pt-BR', 'Dois irmãos, filhos dos mesmos pais, são diferentes entre si em várias características, embora cada um tenha recebido metade do material genético de cada genitor. Qual evento da meiose contribui diretamente para essa variabilidade, além da segregação independente dos cromossomos?', array['A duplicação do DNA na interfase, que produz cópias com combinações novas de alelos','A separação das cromátides-irmãs na anáfase II, que gera combinações novas de alelos','O crossing-over na prófase I, em que cromátides de cromossomos homólogos trocam segmentos','A citocinese ao fim da meiose, que distribui o citoplasma e altera a sequência de genes'], 2, 'O crossing-over (permutação) ocorre na prófase I, quando cromátides de cromossomos homólogos trocam segmentos, gerando gametas com combinações novas de alelos, o que soma à segregação independente na anáfase I. A duplicação do DNA acontece na interfase e mantém a informação idêntica. A separação das cromátides-irmãs na anáfase II não cria combinações novas, pois elas são idênticas. A citocinese apenas divide o citoplasma e não altera o genótipo.', 'medio', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-nat-004', 'biologia', 'biologia.Leis de Mendel e padrões de herança', array['enem','vestibular'], 'pt-BR', 'O albinismo oculocutâneo comum é condicionado por um alelo recessivo (a). Um casal sem albinismo, ambos heterozigotos (Aa), planeja ter um filho. Qual a probabilidade de que a primeira criança seja do sexo masculino e albina? Considere a probabilidade de cada sexo igual a 1/2.', array['1/4','1/2','3/8','1/8'], 3, 'O cruzamento Aa x Aa gera aa com probabilidade 1/4. O sexo é um evento independente com probabilidade 1/2, então a probabilidade conjunta é 1/4 x 1/2 = 1/8. O valor 1/4 considera só o albinismo e esquece o sexo. O valor 1/2 considera apenas o sexo. O valor 3/8 corresponde a menino sem albinismo (3/4 x 1/2), isto é, ao evento complementar quanto ao fenótipo.', 'medio', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-nat-006', 'biologia', 'biologia.Relações ecológicas', array['enem','vestibular'], 'pt-BR', 'Os cupins se alimentam de madeira, mas não digerem a celulose sozinhos. No intestino deles vivem protozoários flagelados que digerem a celulose, recebendo abrigo e alimento. Sem os protozoários, o cupim morre de fome, e sem o cupim os protozoários não sobrevivem. Que relação ecológica descreve essa interação?', array['Comensalismo, pois só os protozoários se beneficiam e o cupim não é afetado','Parasitismo, pois os protozoários se alimentam à custa do cupim e o prejudicam','Mutualismo, pois as duas espécies se beneficiam e não vivem separadas','Predação, pois os protozoários consomem o hospedeiro para obter a celulose'], 2, 'Há benefício mútuo e dependência obrigatória, característica do mutualismo (protocooperação seria a versão facultativa, sem dependência). Comensalismo exige que um se beneficie sem afetar o outro, o que não ocorre, pois ambos ganham. Parasitismo implica prejuízo ao hospedeiro, mas aqui o cupim é beneficiado. Predação envolve a morte do alimento, e os protozoários não matam o cupim para se alimentar.', 'facil', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-nat-008', 'biologia', 'biologia.Sistema cardiovascular', array['vestibular'], 'pt-BR', 'Durante a circulação sistêmica e pulmonar de um adulto saudável, o sangue deixa o ventrículo direito, passa pelos pulmões e retorna ao coração. Qual alternativa descreve corretamente o trajeto e o tipo de sangue no retorno?', array['Pelas veias pulmonares até o átrio esquerdo, trazendo sangue pobre em oxigênio','Pelas veias cavas até o átrio direito, trazendo sangue rico em oxigênio','Pela artéria pulmonar até o átrio direito, trazendo sangue rico em oxigênio','Pelas veias pulmonares até o átrio esquerdo, trazendo sangue rico em oxigênio'], 3, 'O ventrículo direito bombeia sangue pobre em oxigênio pela artéria pulmonar até os pulmões, onde ocorre a hematose. O sangue oxigenado volta pelas veias pulmonares ao átrio esquerdo e segue para o ventrículo esquerdo. A afirmação de sangue venoso nas veias pulmonares é o erro comum, de que toda veia carrega sangue pobre em oxigênio. Retornar ao átrio direito é o trajeto da circulação sistêmica. Pela veia cava chega o sangue da circulação sistêmica, não o dos pulmões.', 'dificil', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-nat-010', 'biologia', 'biologia.Evolução', array['vestibular'], 'pt-BR', 'Em um hospital, uma bactéria deixou de responder a um antibiótico após o uso repetido e inadequado do medicamento. Segundo a teoria da seleção natural, como se explica o surgimento da população resistente?', array['O antibiótico eliminou as bactérias sensíveis e as variantes resistentes, que já existiam, deixaram mais descendentes','O antibiótico induziu mutações específicas que tornaram resistentes as bactérias expostas por necessidade','As bactérias expostas desenvolveram resistência por uso e transmitiram essa característica adquirida','O organismo de cada bactéria aprendeu a neutralizar o fármaco e ensinou essa tolerância às demais'], 0, 'Em qualquer população bacteriana há variação, e alguns indivíduos já possuem, por mutações aleatórias anteriores, genes que conferem resistência. O antibiótico elimina os sensíveis e os resistentes sobrevivem, se reproduzem e passam o gene, aumentando sua frequência. O antibiótico não induz mutações dirigidas nem faz os indivíduos desenvolverem resistência por necessidade (ideia lamarckista). A resistência também não é consequência de aprendizado de cada bactéria, e o uso repetido não a torna hereditária de modo diferente.', 'dificil', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-nat-011', 'fisica', 'fisica.Cinemática', array['enem','vestibular'], 'pt-BR', 'Um carro trafega a 72 km/h em uma rodovia quando o motorista vê um obstáculo e freia, com desaceleração constante de módulo 5 m/s². Qual a distância percorrida até parar?', array['80 m','20 m','40 m','144 m'], 2, 'Convertendo, 72 km/h = 20 m/s. Pela equação de Torricelli, 0 = v² - 2ad, logo d = v²/(2a) = 400/10 = 40 m. O valor 80 m surge de esquecer o fator 2 no denominador (d = v²/a). O valor 20 m aparece ao confundir distância com velocidade inicial em m/s. O valor 144 m resulta de multiplicar 72 por 2 sem converter as unidades para o SI.', 'facil', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-nat-012', 'fisica', 'fisica.Dinâmica', array['enem','vestibular'], 'pt-BR', 'Um bloco de 4 kg desce, sem atrito, uma rampa inclinada de 30° em relação à horizontal. Adote g = 10 m/s², sen 30° = 0,5 e cos 30° = 0,87. Qual a intensidade da força resultante sobre o bloco?', array['40,0 N','34,8 N','5,0 N','20,0 N'], 3, 'Sem atrito, a única componente que acelera o bloco é a do peso paralela ao plano: F = m g sen 30° = 4 x 10 x 0,5 = 20 N. O valor 40 N é o peso inteiro, que ignora a inclinação. O valor 34,8 N usa o cosseno, que é a componente do peso perpendicular ao plano e equilibrada pela normal. O valor 5 N é a aceleração em m/s², e não uma força.', 'medio', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-nat-013', 'fisica', 'fisica.Trabalho e energia', array['enem','vestibular'], 'pt-BR', 'Uma pequena bola de 2 kg é solta do repouso de uma janela situada a 5 m de altura em relação ao solo. Desprezando a resistência do ar e adotando g = 10 m/s², qual a velocidade da bola ao atingir o solo?', array['10 m/s','100 m/s','50 m/s','5 m/s'], 0, 'Pela conservação da energia mecânica, m g h = m v²/2, então v = raiz de (2 g h) = raiz de 100 = 10 m/s. A massa se cancela. O valor 100 m/s é v² e esquece a raiz quadrada. O valor 50 m/s resulta de usar v² = g h, sem o fator 2, e também sem a raiz. O valor 5 m/s é apenas a altura, confundida com a velocidade.', 'medio', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-nat-014', 'fisica', 'fisica.Gravitação', array['vestibular'], 'pt-BR', 'Um planeta tem massa 8 vezes maior e raio 2 vezes maior que os da Terra. Considerando g = 10 m/s² na superfície terrestre, qual o valor aproximado da aceleração da gravidade na superfície desse planeta?', array['40 m/s²','20 m/s²','80 m/s²','5 m/s²'], 1, 'Como g = G M/R², temos g'' = g x (8/2²) = 10 x 2 = 20 m/s². O valor 40 m/s² vem de esquecer de elevar o raio ao quadrado (8/2). O valor 80 m/s² considera só a massa, ignorando o raio. O valor 5 m/s² resulta de inverter a razão entre raio e massa (2²/8) e usar a razão errada.', 'dificil', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-nat-015', 'fisica', 'fisica.Termologia e Termodinâmica', array['enem','vestibular'], 'pt-BR', 'Em um experimento, 200 g de água a 20 °C recebem 6000 cal de uma resistência elétrica, sem perdas. O calor específico da água é 1 cal/(g·°C). Qual a temperatura final da água?', array['30 °C','40 °C','80 °C','50 °C'], 3, 'Pela calorimetria, Q = m c ΔT, logo ΔT = 6000/(200 x 1) = 30 °C, e a temperatura final é 20 + 30 = 50 °C. O valor 30 °C é só a variação, sem somar a temperatura inicial. O valor 40 °C corresponde a usar 300 g na conta, e 80 °C a usar 100 g. Em ambos há erro no valor da massa usada no cálculo da variação.', 'medio', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-nat-016', 'fisica', 'fisica.Ondulatória', array['enem','vestibular'], 'pt-BR', 'Ao tocar uma nota em um instrumento, um músico produz uma onda sonora de frequência 170 Hz e comprimento de onda 2 m no ar. Qual a velocidade de propagação desse som?', array['340 m/s','85 m/s','168 m/s','172 m/s'], 0, 'A equação fundamental da ondulatória é v = λ f = 2 x 170 = 340 m/s, valor próximo ao da velocidade do som no ar. O valor 85 m/s resulta de dividir a frequência pelo comprimento de onda, operação sem significado físico. Os valores 168 m/s e 172 m/s vêm de subtrair ou somar as grandezas, como se fossem de mesma natureza, em vez de multiplicá-las.', 'facil', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-nat-017', 'fisica', 'fisica.Espelhos esféricos', array['vestibular'], 'pt-BR', 'Um espelho esférico côncavo tem distância focal de 20 cm. Um objeto é colocado a 30 cm do vértice do espelho, sobre o eixo principal. A que distância do espelho se forma a imagem?', array['12 cm','60 cm','50 cm','10 cm'], 1, 'Pela equação de Gauss, 1/f = 1/p + 1/p'', logo 1/p'' = 1/20 - 1/30 = 1/60 e p'' = 60 cm, imagem real e invertida, à frente do espelho. O valor 12 cm resulta de tratar o espelho como convexo (f negativo). O valor 50 cm vem de somar f e p, o que não é previsto na equação. O valor 10 cm resulta de subtrair as distâncias em vez de usar os inversos.', 'medio', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-nat-018', 'fisica', 'fisica.Lentes', array['vestibular'], 'pt-BR', 'Uma lupa simples é uma lente convergente de distância focal 10 cm. Um inseto de 3 cm de altura é posicionado a 15 cm da lente, sobre o eixo. Qual o módulo da altura da imagem formada?', array['1,5 cm','9,0 cm','6,0 cm','4,5 cm'], 2, 'Por Gauss, 1/p'' = 1/10 - 1/15 = 1/30, então p'' = 30 cm. O aumento é A = -p''/p = -2, e a altura da imagem é 2 x 3 = 6 cm (real e invertida). O valor 1,5 cm resulta de usar o inverso do aumento. O valor 9 cm usa p''/f em vez de p''/p. O valor 4,5 cm usa p/f como aumento. Em todos o erro está na razão usada para calcular o aumento linear.', 'dificil', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-nat-019', 'fisica', 'fisica.Eletricidade', array['enem'], 'pt-BR', 'Um chuveiro elétrico de 4400 W é usado 20 minutos por dia durante 30 dias. O preço da energia elétrica é de R$ 0,80 por kWh. Qual o custo mensal da energia consumida apenas por esse chuveiro?', array['R$ 105,60','R$ 21,12','R$ 70,40','R$ 35,20'], 3, 'A energia é E = P x t = 4,4 kW x (1/3) h x 30 = 44 kWh, e o custo é 44 x 0,80 = R$ 35,20. O valor R$ 105,60 corresponde a usar 1 hora por dia. O valor R$ 21,12 vem de converter 20 minutos em 0,2 h, em vez de 1/3 h. O valor R$ 70,40 usa 40 minutos por dia, ou seja, duas vezes o tempo informado.', 'facil', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-nat-020', 'fisica', 'fisica.Fluidos', array['enem','vestibular'], 'pt-BR', 'Um mergulhador desce a 20 m de profundidade em um lago de água doce. Considere a densidade da água 1000 kg/m³, g = 10 m/s² e a pressão atmosférica na superfície 100 kPa. Qual a pressão total sobre ele nessa profundidade?', array['200 kPa','120 kPa','300 kPa','100 kPa'], 2, 'A pressão total é a atmosférica mais a hidrostática: p = 100 kPa + ρ g h = 100 + (1000 x 10 x 20)/1000 = 100 + 200 = 300 kPa. O valor 200 kPa considera apenas a coluna de água, esquecendo a pressão da atmosfera. O valor 120 kPa resulta de calcular a hidrostática com profundidade de 2 m. O valor 100 kPa é somente a pressão atmosférica, sem o efeito da profundidade.', 'medio', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-nat-021', 'quimica', 'quimica.Estequiometria', array['enem','vestibular'], 'pt-BR', 'O metano queima segundo CH4 + 2 O2 → CO2 + 2 H2O. Massas molares: CH4 = 16 g/mol, CO2 = 44 g/mol e H2O = 18 g/mol. Qual a massa de CO2 produzida na combustão completa de 32 g de metano?', array['44 g','88 g','176 g','72 g'], 1, '32 g de CH4 correspondem a 2 mol, e a proporção é de 1 CH4 para 1 CO2, logo se formam 2 mol de CO2, ou 2 x 44 = 88 g. O valor 44 g considera 1 mol apenas. O valor 176 g multiplica pelo coeficiente 2 da água, usando proporção errada. O valor 72 g é a massa de água formada (4 mol x 18 g/mol), e não a de dióxido de carbono pedida.', 'medio', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-nat-022', 'quimica', 'quimica.Estequiometria', array['vestibular'], 'pt-BR', 'A decomposição térmica do calcário segue CaCO3 → CaO + CO2. Massas molares: CaCO3 = 100 g/mol, CaO = 56 g/mol, CO2 = 44 g/mol. Em um forno, 100 g de CaCO3 puro são aquecidos e o rendimento da reação é de 80%. Qual a massa de CaO obtida?', array['44,8 g','56,0 g','70,0 g','35,2 g'], 0, '100 g de CaCO3 equivalem a 1 mol, que teoricamente produz 56 g de CaO. Com rendimento de 80%, obtêm-se 0,8 x 56 = 44,8 g. O valor 56 g ignora o rendimento. O valor 70 g divide por 0,8 em vez de multiplicar. O valor 35,2 g aplica o rendimento à massa de CO2 (44 g), e não à de CaO, que é o produto pedido.', 'dificil', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-nat-023', 'quimica', 'quimica.Soluções', array['enem','vestibular'], 'pt-BR', 'Uma solução foi preparada dissolvendo 4 g de hidróxido de sódio (NaOH, massa molar 40 g/mol) em água suficiente para completar 500 mL. Qual a concentração em quantidade de matéria (mol/L) da solução?', array['0,1 mol/L','8,0 mol/L','5,0 mol/L','0,2 mol/L'], 3, 'A quantidade de soluto é n = 4/40 = 0,1 mol, e o volume é 0,5 L, logo C = 0,1/0,5 = 0,2 mol/L. O valor 0,1 é só a quantidade de matéria, sem dividir pelo volume. O valor 8,0 é a razão massa/volume (4 g / 0,5 L), isto é, concentração comum em g/L e não em mol/L. O valor 5,0 inverte a razão e divide o volume pela quantidade de matéria.', 'facil', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-nat-024', 'quimica', 'quimica.Soluções', array['enem','vestibular'], 'pt-BR', 'Em um laboratório de ensino, 100 mL de uma solução de ácido clorídrico 1,5 mol/L são diluídos com água até o volume final de 600 mL. Qual a concentração da solução diluída?', array['0,21 mol/L','0,90 mol/L','0,25 mol/L','4,00 mol/L'], 2, 'A quantidade de soluto não muda: 0,1 L x 1,5 mol/L = 0,15 mol. No volume final de 0,6 L, C = 0,15/0,6 = 0,25 mol/L. O valor 0,21 mol/L soma os 600 mL de água ao volume inicial, ao supor que 600 mL foram adicionados. O valor 0,9 mol/L multiplica a concentração por 0,6 em vez de usar a razão entre volumes. O valor 4,0 mol/L inverte a razão entre os volumes.', 'medio', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-nat-027', 'quimica', 'quimica.Estrutura atômica', array['enem','vestibular'], 'pt-BR', 'O íon alumínio, Al3+, tem número atômico 13 e número de massa 27. Qual a soma do número de nêutrons com o número de elétrons desse íon?', array['27','24','30','23'], 1, 'O número de nêutrons é A - Z = 27 - 13 = 14. O íon 3+ perdeu três elétrons, logo tem 13 - 3 = 10 elétrons. A soma é 24. O valor 27 é o número de massa, que soma prótons e nêutrons. O valor 30 considera que o íon ganhou 3 elétrons (16). O valor 23 usa Z como número de nêutrons e soma 10 elétrons.', 'facil', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-nat-028', 'quimica', 'quimica.Físico-Química', array['enem','vestibular'], 'pt-BR', 'Em um cilindro rígido de 8,2 L, 2 mol de um gás ideal são mantidos a 27 °C. Use R = 0,082 atm·L/(mol·K) e T(K) = T(°C) + 273 (arredondado). Qual a pressão do gás?', array['0,54 atm','3 atm','12 atm','6 atm'], 3, 'Em kelvin, T = 300 K. Pela equação de Clapeyron, P = nRT/V = 2 x 0,082 x 300 / 8,2 = 6 atm. O valor 0,54 atm resulta de usar 27 diretamente, em graus Celsius. O valor 3 atm considera 1 mol em vez de 2. O valor 12 atm vem de usar o volume pela metade na equação.', 'facil', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
insert into content_question_staging (batch_id, source_key, subject, topic_key, categories, locale, prompt, options, correct_index, explanation, difficulty, provenance, validation_state, reference_date, expires_at) select b.id, 'L1-nat-029', 'quimica', 'quimica.Ligações e Estrutura', array['vestibular'], 'pt-BR', 'Duas moléculas, H2O e CO2, apresentam ligações covalentes polares entre os átomos. Mesmo assim, uma delas é polar e a outra é apolar. Qual afirmação explica corretamente esse comportamento?', array['A geometria angular do CO2 anula os dipolos das ligações, enquanto a geometria linear da H2O não os anula','A geometria linear do CO2 anula os dipolos das ligações, enquanto a geometria angular da H2O não os anula','No CO2 os átomos têm eletronegatividade igual, o que impede dipolos, e na H2O eles têm eletronegatividades diferentes','A H2O é polar por ter ligações iônicas entre H e O, e o CO2 é apolar por ter ligações covalentes'], 1, 'O CO2 é linear, e os dois momentos dipolares das ligações C=O têm mesmo módulo e sentidos opostos, cancelando-se, então a molécula é apolar. A água é angular, e os dipolos O-H não se anulam, resultando em molécula polar. A explicação pela eletronegatividade igual está errada, pois O é mais eletronegativo que C e H. A explicação por ligações iônicas na água também está errada, pois H e O compartilham elétrons.', 'medio', '{"origin": "autoral", "refs": []}'::jsonb, 'publicavel', null, null from content_batches b where b.code = 'lote-0001' on conflict (batch_id, source_key) do nothing;
